window.QBANK = window.QBANK || {};
window.QBANK["kuliah-akuntansi"] = {
  level: "Kuliah", subject: "Akuntansi Dasar", duration: 900,
  questions: [
    { q: "Perusahaan Maju Jaya memiliki total aset Rp120.000.000 dan total liabilitas Rp45.000.000. Berapa total ekuitasnya?", options: ["Rp75.000.000", "Rp165.000.000", "Rp45.000.000", "Rp120.000.000"], answer: 0, solution: "1. Gunakan persamaan dasar akuntansi: Aset = Liabilitas + Ekuitas. 2. Ekuitas = Aset − Liabilitas = Rp120.000.000 − Rp45.000.000 = Rp75.000.000. Kesalahan umum: menjumlahkan aset dan liabilitas menjadi Rp165.000.000 karena lupa bahwa ekuitas adalah selisih, bukan jumlah." },
    { q: "Total liabilitas sebuah perusahaan Rp60.000.000 dan total ekuitas Rp90.000.000. Berapa total asetnya?", options: ["Rp30.000.000", "Rp150.000.000", "Rp90.000.000", "Rp60.000.000"], answer: 1, solution: "1. Gunakan persamaan: Aset = Liabilitas + Ekuitas. 2. Aset = Rp60.000.000 + Rp90.000.000 = Rp150.000.000. Kesalahan umum: mengurangkan ekuitas dengan liabilitas (Rp30.000.000) karena tertukar rumus mencari aset dengan mencari liabilitas." },
    { q: "Sebuah perusahaan memiliki total aset Rp200.000.000 dan total ekuitas Rp130.000.000. Berapa total liabilitasnya?", options: ["Rp330.000.000", "Rp130.000.000", "Rp70.000.000", "Rp200.000.000"], answer: 2, solution: "1. Turunkan rumus: Liabilitas = Aset − Ekuitas. 2. Liabilitas = Rp200.000.000 − Rp130.000.000 = Rp70.000.000. Kesalahan umum: menjumlahkan aset dan ekuitas menjadi Rp330.000.000 karena menghafal rumus tanpa memahami posisinya." },
    { q: "Pemilik menyetorkan modal Rp50.000.000 secara tunai ke perusahaan. Pengaruhnya terhadap persamaan dasar akuntansi adalah ...", options: ["Aset bertambah dan liabilitas berkurang", "Aset (kas) bertambah dan ekuitas (modal) bertambah", "Kas berkurang dan modal berkurang", "Hanya komposisi aset yang berubah, totalnya tetap"], answer: 1, solution: "1. Kas (aset) bertambah Rp50.000.000. 2. Modal pemilik (ekuitas) bertambah Rp50.000.000. 3. Kedua sisi persamaan naik sama besar sehingga tetap seimbang. Kesalahan umum: mengira liabilitas ikut berubah, padahal setoran modal tidak melibatkan utang sama sekali." },
    { q: "Perusahaan membeli peralatan kantor Rp10.000.000 secara tunai. Pengaruhnya terhadap persamaan dasar akuntansi adalah ...", options: ["Total aset berkurang Rp10.000.000", "Liabilitas bertambah Rp10.000.000", "Ekuitas berkurang Rp10.000.000", "Total aset tetap, hanya komposisinya berubah"], answer: 3, solution: "1. Kas (aset) berkurang Rp10.000.000, sedangkan peralatan (aset) bertambah Rp10.000.000. 2. Keduanya akun aset, jadi total aset tidak berubah — hanya komposisinya. Kesalahan umum: mengira total aset berkurang karena kas berkurang, lupa bahwa peralatan yang dibeli juga aset." },
    { q: "Perusahaan membayar utang usaha Rp15.000.000 secara tunai. Pengaruhnya terhadap persamaan dasar akuntansi adalah ...", options: ["Kas dan utang usaha masing-masing berkurang Rp15.000.000", "Kas berkurang dan modal bertambah Rp15.000.000", "Hanya utang usaha yang berkurang", "Aset bertambah dan liabilitas berkurang"], answer: 0, solution: "1. Kas (aset) berkurang Rp15.000.000. 2. Utang usaha (liabilitas) berkurang Rp15.000.000. 3. Kedua sisi persamaan turun sama besar sehingga tetap seimbang. Kesalahan umum: mengira ekuitas ikut berubah, padahal pembayaran utang hanya memengaruhi aset dan liabilitas." },
    { q: "Akun Beban Gaji memiliki saldo normal di sisi ...", options: ["Kredit", "Nol", "Tergantung jenis bebannya", "Debit"], answer: 3, solution: "1. Beban mengurangi ekuitas, dan ekuitas berkurang di sisi debit. 2. Karena itu semua akun beban bersaldo normal debit. Kesalahan umum: mengira beban bersaldo kredit dengan logika 'beban itu pengeluaran kas' — padahal sisi pencatatan beban mengikuti pengaruhnya terhadap ekuitas." },
    { q: "Saldo normal akun Pendapatan Jasa adalah ...", options: ["Debit", "Kredit", "Nol", "Tergantung periodenya"], answer: 1, solution: "1. Pendapatan menambah ekuitas, dan ekuitas bertambah di sisi kredit. 2. Maka semua akun pendapatan bersaldo normal kredit. Kesalahan umum: tertukar dengan beban — mendebet pendapatan dengan alasan 'uang masuk', padahal penambahan pendapatan dicatat di kredit." },
    { q: "Akun Prive dicatat di sisi ...", options: ["Kredit karena menambah modal", "Debit karena menambah aset", "Debit karena mengurangi ekuitas", "Kredit karena mengurangi utang"], answer: 2, solution: "1. Prive adalah pengambilan pribadi pemilik yang mengurangi modal (ekuitas). 2. Pengurangan ekuitas dicatat di sisi debit, jadi prive bersaldo normal debit. Kesalahan umum: mengira prive menambah modal atau mencatatnya di sisi kredit." },
    { q: "Akun Utang Bank memiliki saldo normal di sisi ...", options: ["Kredit", "Debit", "Nol", "Tergantung jumlahnya"], answer: 0, solution: "1. Utang bank adalah kewajiban (liabilitas). 2. Liabilitas bertambah di sisi kredit, jadi saldo normalnya kredit. Kesalahan umum: mengira utang bersaldo debit karena mengasosiasikannya dengan 'beban yang harus dibayar'." },
    { q: "Untuk menambah akun Peralatan, pencatatan dilakukan di sisi ...", options: ["Kredit", "Debit", "Tergantung nilainya", "Sisi mana pun boleh"], answer: 1, solution: "1. Peralatan adalah aset dengan saldo normal debit. 2. Penambahan aset dicatat di sisi debit. Kesalahan umum: mengkredit peralatan karena kas yang keluar dicatat di kredit — padahal yang bertambah adalah peralatannya, bukan kasnya." },
    { q: "Jika saldo akun Kas bertambah Rp5.000.000, pencatatannya adalah ...", options: ["Dikredit Rp5.000.000 karena kas bertambah", "Didebet Rp5.000.000 karena kas akun pendapatan", "Tidak dicatat karena belum ada jurnal", "Didebet Rp5.000.000 karena kas adalah aset bersaldo normal debit"], answer: 3, solution: "1. Kas adalah aset dengan saldo normal debit. 2. Penambahan aset dicatat di sisi debit, jadi kas bertambah Rp5.000.000 didebet. Kesalahan umum: mengira setiap penambahan kas dicatat di kredit, atau mengira kas adalah akun pendapatan." },
    { q: "Dibeli perlengkapan kantor Rp2.000.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Kas Rp2.000.000 – Kredit Perlengkapan Rp2.000.000", "Debit Perlengkapan Rp2.000.000 – Kredit Kas Rp2.000.000", "Debit Beban Perlengkapan Rp2.000.000 – Kredit Kas Rp2.000.000", "Debit Perlengkapan Rp2.000.000 – Kredit Utang Usaha Rp2.000.000"], answer: 1, solution: "1. Perlengkapan (aset) bertambah Rp2.000.000 → debit. 2. Kas (aset) berkurang Rp2.000.000 → kredit. 3. Jurnal: Debit Perlengkapan, Kredit Kas. Kesalahan umum: membalik sisi (debet kas) atau langsung mencatat sebagai beban padahal perlengkapan belum terpakai." },
    { q: "Dibeli peralatan Rp5.000.000 secara kredit. Jurnal umum yang benar adalah ...", options: ["Debit Peralatan Rp5.000.000 – Kredit Utang Usaha Rp5.000.000", "Debit Kas Rp5.000.000 – Kredit Peralatan Rp5.000.000", "Debit Peralatan Rp5.000.000 – Kredit Kas Rp5.000.000", "Debit Utang Usaha Rp5.000.000 – Kredit Peralatan Rp5.000.000"], answer: 0, solution: "1. Peralatan (aset) bertambah Rp5.000.000 → debit. 2. Pembelian kredit menimbulkan Utang Usaha (liabilitas) → kredit. 3. Jurnal: Debit Peralatan, Kredit Utang Usaha. Kesalahan umum: mengkredit kas padahal belum ada kas yang keluar." },
    { q: "Diterima pendapatan jasa Rp3.000.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Pendapatan Jasa Rp3.000.000 – Kredit Kas Rp3.000.000", "Debit Piutang Usaha Rp3.000.000 – Kredit Pendapatan Jasa Rp3.000.000", "Debit Kas Rp3.000.000 – Kredit Pendapatan Jasa Rp3.000.000", "Debit Kas Rp3.000.000 – Kredit Modal Rp3.000.000"], answer: 2, solution: "1. Kas (aset) bertambah Rp3.000.000 → debit. 2. Pendapatan Jasa bertambah → kredit (saldo normal pendapatan). 3. Jurnal: Debit Kas, Kredit Pendapatan Jasa. Kesalahan umum: mendebet pendapatan dengan alasan 'uang masuk', atau mencatatnya sebagai penambahan modal." },
    { q: "Dibayar beban listrik Rp500.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Kas Rp500.000 – Kredit Beban Listrik Rp500.000", "Debit Beban Listrik Rp500.000 – Kredit Utang Usaha Rp500.000", "Debit Modal Rp500.000 – Kredit Kas Rp500.000", "Debit Beban Listrik Rp500.000 – Kredit Kas Rp500.000"], answer: 3, solution: "1. Beban Listrik bertambah Rp500.000 → debit (saldo normal beban). 2. Kas berkurang Rp500.000 → kredit. 3. Jurnal: Debit Beban Listrik, Kredit Kas. Kesalahan umum: mengkredit beban atau mendebet kas." },
    { q: "Pemilik menyetorkan modal Rp20.000.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Modal Rp20.000.000 – Kredit Kas Rp20.000.000", "Debit Kas Rp20.000.000 – Kredit Modal Rp20.000.000", "Debit Kas Rp20.000.000 – Kredit Pendapatan Jasa Rp20.000.000", "Debit Prive Rp20.000.000 – Kredit Kas Rp20.000.000"], answer: 1, solution: "1. Kas (aset) bertambah Rp20.000.000 → debit. 2. Modal (ekuitas) bertambah Rp20.000.000 → kredit. 3. Jurnal: Debit Kas, Kredit Modal. Kesalahan umum: mengkredit kas, atau mencatat setoran modal sebagai pendapatan jasa." },
    { q: "Pemilik mengambil uang perusahaan Rp1.000.000 untuk keperluan pribadi (prive). Jurnal yang benar adalah ...", options: ["Debit Prive Rp1.000.000 – Kredit Kas Rp1.000.000", "Debit Beban Gaji Rp1.000.000 – Kredit Kas Rp1.000.000", "Debit Kas Rp1.000.000 – Kredit Prive Rp1.000.000", "Debit Modal Rp1.000.000 – Kredit Kas Rp1.000.000"], answer: 0, solution: "1. Prive (pengurang ekuitas) bertambah Rp1.000.000 → debit. 2. Kas berkurang Rp1.000.000 → kredit. 3. Jurnal: Debit Prive, Kredit Kas. Kesalahan umum: mencatat prive sebagai beban, atau langsung mendebet modal tanpa melalui akun prive." },
    { q: "Jasa telah dikerjakan senilai Rp2.500.000 tetapi pelanggan belum membayar. Jurnal yang benar adalah ...", options: ["Debit Kas Rp2.500.000 – Kredit Pendapatan Jasa Rp2.500.000", "Debit Pendapatan Jasa Rp2.500.000 – Kredit Piutang Usaha Rp2.500.000", "Debit Piutang Usaha Rp2.500.000 – Kredit Pendapatan Jasa Rp2.500.000", "Tidak perlu dijurnal sampai kas diterima"], answer: 2, solution: "1. Jasa sudah dikerjakan → Pendapatan Jasa bertambah Rp2.500.000 → kredit. 2. Kas belum diterima → timbul Piutang Usaha (aset) → debit. 3. Jurnal: Debit Piutang Usaha, Kredit Pendapatan Jasa. Kesalahan umum: mendebet kas padahal kas belum diterima — basis akrual mengakui pendapatan saat dihasilkan, bukan saat kas diterima." },
    { q: "Akun Kas bersaldo awal debit Rp10.000.000, selama periode ada mutasi debit Rp5.000.000 dan mutasi kredit Rp3.000.000. Saldo akhir Kas adalah ...", options: ["Rp8.000.000 (debit)", "Rp12.000.000 (debit)", "Rp18.000.000 (debit)", "Rp2.000.000 (kredit)"], answer: 1, solution: "1. Untuk akun bersaldo normal debit: saldo akhir = saldo awal + mutasi debit − mutasi kredit. 2. Rp10.000.000 + Rp5.000.000 − Rp3.000.000 = Rp12.000.000 (debit). Kesalahan umum: menjumlahkan semua mutasi tanpa memperhatikan sisi (mendapat Rp18.000.000) atau mengurangkan mutasi debit." },
    { q: "Ciri neraca saldo yang benar adalah ...", options: ["Total sisi debit sama dengan total sisi kredit", "Semua akun harus bersaldo nol", "Total aset sama dengan total pendapatan", "Jumlah akun debit sama dengan jumlah akun kredit"], answer: 0, solution: "1. Setiap jurnal selalu seimbang (total debit = total kredit). 2. Karena neraca saldo meringkas semua saldo buku besar, total sisi debit harus sama dengan total sisi kredit. Kesalahan umum: mengira neraca saldo harus bersaldo nol, atau yang harus sama adalah jumlah akunnya." },
    { q: "Berikut ini akun yang bersaldo normal kredit adalah ...", options: ["Kas", "Peralatan", "Beban Sewa", "Utang Usaha"], answer: 3, solution: "1. Kas, peralatan, dan beban sewa bersaldo normal debit (aset dan beban). 2. Utang usaha adalah liabilitas yang bersaldo normal kredit. Kesalahan umum: mengira semua akun yang muncul di neraca saldo bersaldo debit." },
    { q: "Jika neraca saldo tidak seimbang (total debit tidak sama dengan total kredit), kemungkinan penyebabnya adalah ...", options: ["Perusahaan dipastikan mengalami kerugian", "Neraca saldo harus dibuat ulang dari awal tanpa dicek", "Ada kesalahan pencatatan seperti salah sisi, salah jumlah, atau salah posting", "Akun modal harus ditambah agar seimbang"], answer: 2, solution: "1. Ketidakseimbangan berarti ada kesalahan mekanis dalam pencatatan. 2. Penyebab umum: salah sisi (debit dicatat kredit), salah jumlah angka, atau lupa memposting satu sisi jurnal ke buku besar. Kesalahan umum: mengira ketidakseimbangan berarti perusahaan rugi, atau menutup selisih dengan menambah akun fiktif." },
    { q: "Dalam neraca saldo, akun Pendapatan Jasa ternyata bersaldo debit. Hal ini menunjukkan ...", options: ["Kondisi yang normal untuk akun pendapatan", "Kemungkinan kesalahan pencatatan yang perlu ditelusuri", "Bukti perusahaan sangat menguntungkan", "Pendapatan diterima di muka yang belum diakui"], answer: 1, solution: "1. Pendapatan bersaldo normal kredit. 2. Saldo debit pada akun pendapatan adalah saldo abnormal yang menandakan kemungkinan salah jurnal (misalnya retur atau koreksi yang salah sisi). Kesalahan umum: menganggapnya normal-normal saja atau langsung menghapus akunnya tanpa menelusuri jurnal sumbernya." },
    { q: "Dibayar sewa Rp12.000.000 untuk 12 bulan. Pada akhir periode, sewa yang sudah terpakai 3 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Sewa Rp3.000.000 – Kredit Sewa Dibayar di Muka Rp3.000.000", "Debit Sewa Dibayar di Muka Rp12.000.000 – Kredit Beban Sewa Rp12.000.000", "Debit Beban Sewa Rp12.000.000 – Kredit Kas Rp12.000.000", "Debit Beban Sewa Rp9.000.000 – Kredit Sewa Dibayar di Muka Rp9.000.000"], answer: 0, solution: "1. Sewa per bulan = Rp12.000.000 ÷ 12 = Rp1.000.000. 2. Terpakai 3 bulan → beban sewa = 3 × Rp1.000.000 = Rp3.000.000. 3. Jurnal: Debit Beban Sewa Rp3.000.000, Kredit Sewa Dibayar di Muka Rp3.000.000. Kesalahan umum: mencatat seluruh Rp12.000.000 sebagai beban sekaligus, atau menjurnal sisanya (Rp9.000.000) sebagai beban." },
    { q: "Diterima di muka pendapatan jasa Rp6.000.000 untuk 6 bulan pengerjaan. Pada akhir periode, jasa yang sudah dikerjakan 2 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Pendapatan Jasa Rp6.000.000 – Kredit Kas Rp6.000.000", "Debit Kas Rp2.000.000 – Kredit Pendapatan Diterima di Muka Rp2.000.000", "Debit Pendapatan Diterima di Muka Rp2.000.000 – Kredit Pendapatan Jasa Rp2.000.000", "Debit Pendapatan Diterima di Muka Rp6.000.000 – Kredit Pendapatan Jasa Rp6.000.000"], answer: 2, solution: "1. Jasa per bulan = Rp6.000.000 ÷ 6 = Rp1.000.000. 2. Sudah dikerjakan 2 bulan → pendapatan yang diakui = 2 × Rp1.000.000 = Rp2.000.000. 3. Jurnal: Debit Pendapatan Diterima di Muka Rp2.000.000, Kredit Pendapatan Jasa Rp2.000.000. Kesalahan umum: mengakui seluruh Rp6.000.000 sebagai pendapatan periode ini." },
    { q: "Gaji karyawan bulan Desember Rp4.500.000 belum dibayar sampai akhir periode. Jurnal penyesuaiannya adalah ...", options: ["Debit Utang Gaji Rp4.500.000 – Kredit Kas Rp4.500.000", "Debit Kas Rp4.500.000 – Kredit Beban Gaji Rp4.500.000", "Tidak perlu jurnal karena belum dibayar", "Debit Beban Gaji Rp4.500.000 – Kredit Utang Gaji Rp4.500.000"], answer: 3, solution: "1. Gaji Desember sudah menjadi beban periode ini walaupun belum dibayar (beban akrual). 2. Jurnal: Debit Beban Gaji Rp4.500.000, Kredit Utang Gaji Rp4.500.000. Kesalahan umum: tidak mencatat apa-apa dengan alasan 'belum dibayar', sehingga beban dan utang dilaporkan terlalu rendah." },
    { q: "Jasa senilai Rp7.000.000 sudah dikerjakan pada akhir periode tetapi belum ditagih ke pelanggan. Jurnal penyesuaiannya adalah ...", options: ["Debit Kas Rp7.000.000 – Kredit Pendapatan Jasa Rp7.000.000", "Debit Piutang Usaha Rp7.000.000 – Kredit Pendapatan Jasa Rp7.000.000", "Debit Pendapatan Jasa Rp7.000.000 – Kredit Piutang Usaha Rp7.000.000", "Tidak dijurnal sampai faktur diterbitkan"], answer: 1, solution: "1. Jasa sudah dikerjakan → pendapatan akrual periode ini Rp7.000.000. 2. Belum ditagih → Debit Piutang Usaha, Kredit Pendapatan Jasa. Kesalahan umum: menunggu faktur terbit baru mencatat, sehingga pendapatan periode ini dilaporkan terlalu rendah." },
    { q: "Beban depresiasi peralatan tahun ini Rp1.200.000. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Depresiasi Rp1.200.000 – Kredit Akumulasi Depresiasi Rp1.200.000", "Debit Akumulasi Depresiasi Rp1.200.000 – Kredit Beban Depresiasi Rp1.200.000", "Debit Beban Depresiasi Rp1.200.000 – Kredit Peralatan Rp1.200.000", "Debit Peralatan Rp1.200.000 – Kredit Kas Rp1.200.000"], answer: 0, solution: "1. Depresiasi adalah alokasi beban, bukan pengurangan langsung nilai asetnya. 2. Jurnal: Debit Beban Depresiasi Rp1.200.000, Kredit Akumulasi Depresiasi Rp1.200.000. Kesalahan umum: mengkredit langsung akun Peralatan sehingga harga perolehan aset hilang dari catatan." },
    { q: "Saldo akun Perlengkapan Rp3.000.000, sedangkan hasil opname fisik menunjukkan sisa Rp800.000. Jurnal penyesuaiannya adalah ...", options: ["Debit Perlengkapan Rp2.200.000 – Kredit Beban Perlengkapan Rp2.200.000", "Debit Beban Perlengkapan Rp800.000 – Kredit Perlengkapan Rp800.000", "Debit Beban Perlengkapan Rp2.200.000 – Kredit Perlengkapan Rp2.200.000", "Debit Beban Perlengkapan Rp3.000.000 – Kredit Kas Rp3.000.000"], answer: 2, solution: "1. Perlengkapan terpakai = saldo awal − sisa = Rp3.000.000 − Rp800.000 = Rp2.200.000. 2. Jurnal: Debit Beban Perlengkapan Rp2.200.000, Kredit Perlengkapan Rp2.200.000. Kesalahan umum: menjurnal sisa Rp800.000 sebagai beban, padahal yang menjadi beban adalah yang terpakai." },
    { q: "Jika jurnal penyesuaian untuk beban dibayar di muka tidak dibuat, dampaknya terhadap laporan keuangan adalah ...", options: ["Laba bersih terlalu rendah dan aset terlalu rendah", "Tidak ada dampak karena tidak ada kas yang bergerak", "Beban terlalu tinggi dan utang terlalu rendah", "Beban terlalu rendah dan laba bersih terlalu tinggi"], answer: 3, solution: "1. Tanpa penyesuaian, beban yang sudah terpakai belum diakui → beban dilaporkan terlalu rendah. 2. Beban rendah → laba bersih terlalu tinggi, dan aset (sewa dibayar di muka) juga terlalu tinggi. Kesalahan umum: mengira tidak ada dampak dengan alasan 'tidak ada kas yang bergerak' — padahal penyesuaian justru untuk transaksi non-kas." },
    { q: "Sebuah mesin dibeli Rp60.000.000 dengan nilai sisa Rp12.000.000 dan umur manfaat 4 tahun. Beban depresiasi per tahun metode garis lurus adalah ...", options: ["Rp15.000.000", "Rp12.000.000", "Rp3.000.000", "Rp48.000.000"], answer: 1, solution: "1. Rumus garis lurus: (Harga perolehan − Nilai sisa) ÷ Umur manfaat. 2. (Rp60.000.000 − Rp12.000.000) ÷ 4 = Rp48.000.000 ÷ 4 = Rp12.000.000 per tahun. Kesalahan umum: tidak mengurangkan nilai sisa sehingga mendapat Rp15.000.000." },
    { q: "Mesin pada soal sebelumnya (harga Rp60.000.000, depresiasi Rp12.000.000 per tahun) telah dipakai selama 2 tahun. Nilai buku mesin tersebut adalah ...", options: ["Rp36.000.000", "Rp24.000.000", "Rp12.000.000", "Rp48.000.000"], answer: 0, solution: "1. Akumulasi depresiasi 2 tahun = 2 × Rp12.000.000 = Rp24.000.000. 2. Nilai buku = Harga perolehan − Akumulasi depresiasi = Rp60.000.000 − Rp24.000.000 = Rp36.000.000. Kesalahan umum: mengurangkan nilai sisa sekali lagi, atau mengira nilai buku sama dengan akumulasi depresiasinya." },
    { q: "Mesin Rp100.000.000, nilai sisa Rp10.000.000, umur manfaat 5 tahun, baru dipakai 3 bulan pada tahun pertama. Beban depresiasi tahun pertama adalah ...", options: ["Rp18.000.000", "Rp90.000.000", "Rp4.500.000", "Rp1.500.000"], answer: 2, solution: "1. Depresiasi per tahun = (Rp100.000.000 − Rp10.000.000) ÷ 5 = Rp18.000.000. 2. Baru dipakai 3 bulan → Rp18.000.000 × 3/12 = Rp4.500.000. Kesalahan umum: mencatat depresiasi setahun penuh Rp18.000.000 walaupun aset baru dipakai 3 bulan." },
    { q: "Akun Akumulasi Depresiasi diklasifikasikan sebagai ...", options: ["Aset lancar", "Liabilitas jangka panjang", "Beban operasional", "Akun kontra aset"], answer: 3, solution: "1. Akumulasi depresiasi mengurangi nilai aset tetap di neraca. 2. Karena mengurangi aset tetapi bersaldo kredit, ia disebut akun kontra aset. Kesalahan umum: mengira akumulasi depresiasi adalah beban (padahal bebannya adalah Beban Depresiasi) atau liabilitas." },
    { q: "Kendaraan dibeli Rp150.000.000, nilai sisa Rp30.000.000, umur manfaat 6 tahun. Setelah dipakai 3 tahun, nilai bukunya adalah ...", options: ["Rp60.000.000", "Rp90.000.000", "Rp20.000.000", "Rp120.000.000"], answer: 1, solution: "1. Depresiasi per tahun = (Rp150.000.000 − Rp30.000.000) ÷ 6 = Rp20.000.000. 2. Akumulasi 3 tahun = 3 × Rp20.000.000 = Rp60.000.000. 3. Nilai buku = Rp150.000.000 − Rp60.000.000 = Rp90.000.000. Kesalahan umum: mengurangkan nilai sisa dua kali, atau lupa mengalikan depresiasi tahunan dengan jumlah tahun pemakaian." },
    { q: "Pendapatan usaha Rp80.000.000 dan harga pokok penjualan Rp45.000.000. Laba kotor perusahaan adalah ...", options: ["Rp125.000.000", "Rp45.000.000", "Rp35.000.000", "Rp80.000.000"], answer: 2, solution: "1. Laba kotor = Pendapatan − Harga Pokok Penjualan. 2. Rp80.000.000 − Rp45.000.000 = Rp35.000.000. Kesalahan umum: menjumlahkan pendapatan dan HPP menjadi Rp125.000.000." },
    { q: "Laba kotor Rp35.000.000 dan total beban operasional Rp22.000.000. Laba bersih perusahaan adalah ...", options: ["Rp13.000.000", "Rp57.000.000", "Rp22.000.000", "Rp35.000.000"], answer: 0, solution: "1. Laba bersih = Laba kotor − Beban operasional. 2. Rp35.000.000 − Rp22.000.000 = Rp13.000.000. Kesalahan umum: menambah beban ke laba kotor (Rp57.000.000) atau mengurangkan HPP dua kali." },
    { q: "Total pendapatan Rp50.000.000 sedangkan total beban Rp58.000.000. Kondisi perusahaan adalah ...", options: ["Laba bersih Rp8.000.000", "Rugi bersih Rp8.000.000", "Laba bersih Rp108.000.000", "Impas (tidak laba tidak rugi)"], answer: 1, solution: "1. Selisih = Rp50.000.000 − Rp58.000.000 = −Rp8.000.000. 2. Hasil negatif berarti perusahaan mengalami rugi bersih Rp8.000.000. Kesalahan umum: tetap menyebutnya laba bersih, atau membalik sehingga seolah labanya Rp8.000.000." },
    { q: "Dalam laporan laba rugi, akun-akun beban disajikan sebagai ...", options: ["Penambah pendapatan", "Aset lancar", "Bagian dari ekuitas", "Pengurang pendapatan"], answer: 3, solution: "1. Beban bersaldo normal debit dan mengurangi ekuitas. 2. Dalam laporan laba rugi, beban disajikan sebagai pengurang pendapatan untuk menghasilkan laba (rugi) bersih. Kesalahan umum: mengira beban menambah pendapatan karena 'beban juga angka positif dalam laporan'." },
    { q: "Modal awal Rp100.000.000, laba bersih Rp13.000.000, dan prive Rp5.000.000. Modal akhir periode adalah ...", options: ["Rp108.000.000", "Rp118.000.000", "Rp92.000.000", "Rp105.000.000"], answer: 0, solution: "1. Rumus: Modal akhir = Modal awal + Laba bersih − Prive. 2. Rp100.000.000 + Rp13.000.000 − Rp5.000.000 = Rp108.000.000. Kesalahan umum: menambah prive menjadi Rp118.000.000 karena lupa bahwa prive mengurangi modal." },
    { q: "Modal awal Rp80.000.000, rugi bersih Rp8.000.000, dan prive Rp2.000.000. Modal akhir periode adalah ...", options: ["Rp90.000.000", "Rp74.000.000", "Rp70.000.000", "Rp86.000.000"], answer: 2, solution: "1. Modal akhir = Modal awal − Rugi bersih − Prive. 2. Rp80.000.000 − Rp8.000.000 − Rp2.000.000 = Rp70.000.000. 3. Rugi bersih dan prive sama-sama mengurangi modal. Kesalahan umum: hanya mengurangkan salah satunya, misalnya lupa mengurangkan prive." },
    { q: "Rumus modal akhir yang benar dalam laporan perubahan modal adalah ...", options: ["Modal awal − Laba bersih + Prive", "Modal awal + Laba bersih − Prive + Setoran tambahan", "Modal awal + Prive − Laba bersih", "Aset − Liabilitas + Prive"], answer: 1, solution: "1. Laba bersih menambah modal, sedangkan rugi bersih dan prive mengurangi modal; setoran tambahan menambah modal. 2. Rumus lengkap: Modal awal + Laba bersih − Prive + Setoran tambahan. Kesalahan umum: menempatkan prive sebagai penambah modal." },
    { q: "Berikut ini kelompok aset lancar, KECUALI ...", options: ["Kas", "Piutang usaha", "Perlengkapan", "Gedung"], answer: 3, solution: "1. Aset lancar adalah aset yang dapat menjadi kas dalam satu tahun: kas, piutang usaha, dan perlengkapan. 2. Gedung dipakai lebih dari satu tahun sehingga termasuk aset tetap. Kesalahan umum: mengira semua aset berwujud otomatis aset lancar." },
    { q: "Dalam neraca, total aset Rp200.000.000 dan total liabilitas Rp75.000.000. Total ekuitas yang dilaporkan sebesar ...", options: ["Rp125.000.000", "Rp275.000.000", "Rp75.000.000", "Rp200.000.000"], answer: 0, solution: "1. Neraca harus seimbang: Aset = Liabilitas + Ekuitas. 2. Ekuitas = Rp200.000.000 − Rp75.000.000 = Rp125.000.000. Kesalahan umum: menjumlahkan aset dan liabilitas menjadi Rp275.000.000." },
    { q: "Akun berikut yang TIDAK dilaporkan dalam neraca adalah ...", options: ["Kas", "Utang usaha", "Beban gaji", "Modal pemilik"], answer: 2, solution: "1. Neraca hanya memuat akun riil: aset, liabilitas, dan ekuitas. 2. Beban gaji adalah akun nominal yang dilaporkan di laporan laba rugi, bukan di neraca. Kesalahan umum: memasukkan beban ke neraca dengan alasan 'beban mengurangi modal'." },
    { q: "Pembelian mesin Rp40.000.000 secara tunai diklasifikasikan dalam laporan arus kas sebagai aktivitas ...", options: ["Operasi", "Investasi", "Pendanaan", "Non-kas"], answer: 1, solution: "1. Pembelian aset tetap jangka panjang termasuk aktivitas investasi. 2. Aktivitas operasi hanya mencakup transaksi rutin sehari-hari seperti penerimaan dari pelanggan dan pembayaran ke pemasok. Kesalahan umum: mengklasifikasikannya sebagai aktivitas operasi hanya karena mengeluarkan kas." },
    { q: "Kas diterima dari pelanggan Rp30.000.000 dan kas dibayar ke pemasok Rp18.000.000. Arus kas bersih dari aktivitas operasi sebesar ...", options: ["Rp48.000.000", "Rp30.000.000", "Rp18.000.000", "Rp12.000.000"], answer: 3, solution: "1. Arus kas operasi = kas masuk operasi − kas keluar operasi. 2. Rp30.000.000 − Rp18.000.000 = Rp12.000.000. Kesalahan umum: menjumlahkan keduanya menjadi Rp48.000.000." },
    { q: "Prinsip yang mengharuskan beban diakui pada periode yang sama dengan pendapatan yang dihasilkannya disebut ...", options: ["Going concern", "Konservatisme", "Prinsip penandingan (matching principle)", "Biaya historis"], answer: 2, solution: "1. Prinsip penandingan (matching principle) menuntut beban diakui pada periode yang sama dengan pendapatan yang dihasilkannya. 2. Inilah dasar dibuatnya jurnal penyesuaian seperti beban akrual dan depresiasi. Kesalahan umum: mengacaukannya dengan konservatisme (kehati-hatian) atau going concern (kelangsungan usaha)." },
    { q: "Berdasarkan basis akrual, pendapatan jasa Rp7.000.000 yang sudah dikerjakan tetapi kasnya belum diterima harus ...", options: ["Diakui sebagai pendapatan periode ini", "Diakui sebagai pendapatan saat kas diterima", "Dicatat sebagai liabilitas", "Diabaikan karena belum ada kas"], answer: 0, solution: "1. Basis akrual mengakui pendapatan saat dihasilkan (earned), bukan saat kas diterima. 2. Maka Rp7.000.000 diakui sebagai pendapatan periode ini dengan jurnal Debit Piutang Usaha, Kredit Pendapatan Jasa. Kesalahan umum: menunggu kas diterima dulu baru mencatat — itu adalah basis kas, bukan basis akrual." },
    { q: "PT Cahaya Abadi memiliki total aset Rp350.000.000 dan total liabilitas Rp125.000.000. Berapa total ekuitasnya?", options: ["Rp225.000.000", "Rp475.000.000", "Rp125.000.000", "Rp350.000.000"], answer: 0, solution: "1. Gunakan persamaan dasar akuntansi: Aset = Liabilitas + Ekuitas. 2. Ekuitas = Aset − Liabilitas = Rp350.000.000 − Rp125.000.000 = Rp225.000.000. Kesalahan umum: menjumlahkan aset dan liabilitas menjadi Rp475.000.000 karena lupa bahwa ekuitas adalah selisih keduanya." },
    { q: "UD Barokah memiliki total liabilitas Rp42.000.000 dan total ekuitas Rp58.000.000. Berapa total asetnya?", options: ["Rp16.000.000", "Rp100.000.000", "Rp58.000.000", "Rp42.000.000"], answer: 1, solution: "1. Gunakan persamaan: Aset = Liabilitas + Ekuitas. 2. Aset = Rp42.000.000 + Rp58.000.000 = Rp100.000.000. Kesalahan umum: mengurangkan ekuitas dengan liabilitas (Rp16.000.000) karena tertukar rumus mencari aset dengan mencari liabilitas." },
    { q: "Toko Makmur memiliki total aset Rp88.000.000 dan total ekuitas Rp52.000.000. Berapa total liabilitasnya?", options: ["Rp140.000.000", "Rp52.000.000", "Rp36.000.000", "Rp88.000.000"], answer: 2, solution: "1. Turunkan rumus: Liabilitas = Aset − Ekuitas. 2. Liabilitas = Rp88.000.000 − Rp52.000.000 = Rp36.000.000. Kesalahan umum: menjumlahkan aset dan ekuitas menjadi Rp140.000.000." },
    { q: "Bengkel Jaya memiliki ekuitas Rp75.000.000 dan liabilitas Rp25.000.000. Berapa total asetnya?", options: ["Rp100.000.000", "Rp50.000.000", "Rp75.000.000", "Rp25.000.000"], answer: 0, solution: "1. Aset = Liabilitas + Ekuitas. 2. Aset = Rp25.000.000 + Rp75.000.000 = Rp100.000.000. Kesalahan umum: mengurangkan ekuitas dengan liabilitas menjadi Rp50.000.000." },
    { q: "PT Artha Graha memiliki total aset Rp500.000.000 dan total liabilitas Rp310.000.000. Berapa total ekuitasnya?", options: ["Rp810.000.000", "Rp310.000.000", "Rp500.000.000", "Rp190.000.000"], answer: 3, solution: "1. Ekuitas = Aset − Liabilitas. 2. Ekuitas = Rp500.000.000 − Rp310.000.000 = Rp190.000.000. Kesalahan umum: menjumlahkan keduanya menjadi Rp810.000.000." },
    { q: "Kafe Rasa memiliki liabilitas Rp18.500.000 dan ekuitas Rp31.500.000. Berapa total asetnya?", options: ["Rp13.000.000", "Rp50.000.000", "Rp31.500.000", "Rp18.500.000"], answer: 1, solution: "1. Aset = Liabilitas + Ekuitas. 2. Aset = Rp18.500.000 + Rp31.500.000 = Rp50.000.000. Kesalahan umum: mengurangkan ekuitas dengan liabilitas menjadi Rp13.000.000." },
    { q: "Laundry Bersih memiliki total aset Rp45.000.000 dan total ekuitas Rp27.000.000. Berapa total liabilitasnya?", options: ["Rp18.000.000", "Rp72.000.000", "Rp27.000.000", "Rp45.000.000"], answer: 0, solution: "1. Liabilitas = Aset − Ekuitas. 2. Liabilitas = Rp45.000.000 − Rp27.000.000 = Rp18.000.000. Kesalahan umum: menjumlahkan aset dan ekuitas menjadi Rp72.000.000." },
    { q: "Perusahaan membeli kendaraan Rp40.000.000 dengan utang bank. Bagaimana pengaruhnya terhadap ekuitas?", options: ["Ekuitas bertambah Rp40.000.000", "Ekuitas tetap, karena kenaikan aset diimbangi kenaikan liabilitas", "Ekuitas berkurang Rp40.000.000", "Ekuitas bertambah Rp80.000.000"], answer: 1, solution: "1. Kendaraan (aset) bertambah Rp40.000.000 dan Utang Bank (liabilitas) bertambah Rp40.000.000. 2. Karena kedua sisi naik sama besar, ekuitas tidak berubah. Kesalahan umum: mengira setiap penambahan aset otomatis menambah ekuitas." },
    { q: "CV Sinar Terang memiliki aset Rp240.000.000, liabilitas Rp90.000.000, dan ekuitas Rp150.000.000. Kondisi persamaan dasarnya adalah ...", options: ["Seimbang, karena Rp240.000.000 = Rp90.000.000 + Rp150.000.000", "Tidak seimbang, selisih Rp60.000.000", "Tidak seimbang, selisih Rp150.000.000", "Seimbang, karena Rp240.000.000 = Rp150.000.000 − Rp90.000.000"], answer: 0, solution: "1. Uji persamaan: Liabilitas + Ekuitas = Rp90.000.000 + Rp150.000.000 = Rp240.000.000. 2. Hasilnya sama dengan total aset, jadi persamaan seimbang. Kesalahan umum: memakai rumus terbalik (ekuitas − liabilitas) lalu menyimpulkan tidak seimbang." },
    { q: "Total aset perusahaan Rp100.000.000 dan total ekuitas Rp60.000.000. Berapa total liabilitasnya?", options: ["Rp160.000.000", "Rp60.000.000", "Rp40.000.000", "Rp100.000.000"], answer: 2, solution: "1. Liabilitas = Aset − Ekuitas. 2. Liabilitas = Rp100.000.000 − Rp60.000.000 = Rp40.000.000. Kesalahan umum: menjumlahkan aset dan ekuitas menjadi Rp160.000.000." },
    { q: "Persamaan dasar akuntansi yang benar adalah ...", options: ["Aset = Liabilitas − Ekuitas", "Liabilitas = Aset + Ekuitas", "Ekuitas = Liabilitas − Aset", "Aset = Liabilitas + Ekuitas"], answer: 3, solution: "1. Persamaan dasar akuntansi menyatakan bahwa seluruh aset didanai oleh liabilitas dan ekuitas. 2. Rumus yang benar: Aset = Liabilitas + Ekuitas. Kesalahan umum: menghafal urutan terbalik sehingga menempatkan liabilitas atau ekuitas di sisi yang salah." },
    { q: "Salon Cantik memiliki total aset Rp72.000.000 dan total liabilitas Rp28.000.000. Berapa total ekuitasnya?", options: ["Rp100.000.000", "Rp44.000.000", "Rp28.000.000", "Rp72.000.000"], answer: 1, solution: "1. Ekuitas = Aset − Liabilitas. 2. Ekuitas = Rp72.000.000 − Rp28.000.000 = Rp44.000.000. Kesalahan umum: menjumlahkan aset dan liabilitas menjadi Rp100.000.000." },
    { q: "Perusahaan membeli kendaraan Rp60.000.000 dengan membayar tunai Rp20.000.000 dan sisanya kredit. Pengaruhnya terhadap persamaan dasar adalah ...", options: ["Aset bertambah bersih Rp40.000.000 dan liabilitas bertambah Rp40.000.000", "Aset berkurang Rp20.000.000 dan liabilitas bertambah Rp40.000.000", "Aset bertambah Rp60.000.000 dan ekuitas bertambah Rp60.000.000", "Total aset tetap dan liabilitas bertambah Rp40.000.000"], answer: 0, solution: "1. Kendaraan (aset) bertambah Rp60.000.000, Kas (aset) berkurang Rp20.000.000, sehingga aset neto bertambah Rp40.000.000. 2. Utang Usaha (liabilitas) bertambah Rp40.000.000. 3. Kenaikan aset neto diimbangi kenaikan liabilitas. Kesalahan umum: hanya mencatat kas yang keluar tanpa menghitung kendaraan yang masuk." },
    { q: "Perusahaan menerima pinjaman bank Rp50.000.000 secara tunai. Pengaruhnya terhadap persamaan dasar adalah ...", options: ["Aset bertambah dan ekuitas bertambah Rp50.000.000", "Kas bertambah dan utang bank bertambah Rp50.000.000", "Hanya komposisi aset yang berubah", "Kas berkurang dan utang bank bertambah"], answer: 1, solution: "1. Kas (aset) bertambah Rp50.000.000. 2. Utang Bank (liabilitas) bertambah Rp50.000.000. 3. Ekuitas tidak berubah karena ini transaksi pendanaan, bukan pendapatan. Kesalahan umum: mengira pinjaman bank menambah modal/ekuitas." },
    { q: "Perusahaan membayar beban gaji Rp6.000.000 secara tunai. Pengaruhnya terhadap persamaan dasar adalah ...", options: ["Kas berkurang dan utang gaji berkurang Rp6.000.000", "Aset (kas) berkurang dan ekuitas berkurang Rp6.000.000", "Hanya komposisi aset yang berubah", "Aset bertambah dan liabilitas berkurang"], answer: 1, solution: "1. Kas (aset) berkurang Rp6.000.000. 2. Beban gaji mengurangi ekuitas sebesar Rp6.000.000. 3. Kedua sisi turun sama besar. Kesalahan umum: mengira pembayaran beban hanya memengaruhi aset tanpa menyentuh ekuitas." },
    { q: "Perusahaan menerima pendapatan jasa Rp8.000.000 secara tunai. Pengaruhnya terhadap persamaan dasar adalah ...", options: ["Kas berkurang dan modal berkurang", "Aset (kas) bertambah dan ekuitas bertambah Rp8.000.000", "Hanya liabilitas yang bertambah", "Aset bertambah dan liabilitas bertambah"], answer: 1, solution: "1. Kas (aset) bertambah Rp8.000.000. 2. Pendapatan menambah ekuitas sebesar Rp8.000.000. 3. Kedua sisi naik sama besar. Kesalahan umum: mengira pendapatan menambah liabilitas." },
    { q: "Perusahaan membeli perlengkapan Rp3.000.000 secara kredit. Pengaruhnya terhadap persamaan dasar adalah ...", options: ["Aset bertambah dan liabilitas bertambah Rp3.000.000", "Hanya komposisi aset yang berubah", "Aset berkurang dan liabilitas bertambah", "Ekuitas berkurang Rp3.000.000"], answer: 0, solution: "1. Perlengkapan (aset) bertambah Rp3.000.000. 2. Utang Usaha (liabilitas) bertambah Rp3.000.000. 3. Persamaan tetap seimbang. Kesalahan umum: mencatatnya sebagai beban sehingga mengira ekuitas berkurang." },
    { q: "Pemilik menyetorkan peralatan senilai Rp15.000.000 sebagai tambahan modal (bukan tunai). Pengaruhnya adalah ...", options: ["Kas bertambah dan modal bertambah Rp15.000.000", "Peralatan (aset) bertambah dan modal (ekuitas) bertambah Rp15.000.000", "Hanya komposisi aset yang berubah", "Peralatan bertambah dan utang bertambah"], answer: 1, solution: "1. Peralatan (aset) bertambah Rp15.000.000. 2. Modal (ekuitas) bertambah Rp15.000.000. 3. Setoran modal tidak harus berupa kas — bisa berupa aset non-kas. Kesalahan umum: mengira setoran modal selalu menambah kas." },
    { q: "Perusahaan menerima pelunasan piutang Rp7.000.000 secara tunai. Pengaruhnya adalah ...", options: ["Aset bertambah Rp7.000.000 dan ekuitas bertambah", "Kas bertambah dan piutang berkurang Rp7.000.000, total aset tetap", "Liabilitas berkurang Rp7.000.000", "Kas bertambah dan pendapatan bertambah"], answer: 1, solution: "1. Kas (aset) bertambah Rp7.000.000. 2. Piutang Usaha (aset) berkurang Rp7.000.000. 3. Keduanya akun aset, jadi total aset tetap — hanya komposisinya berubah. Pendapatan sudah diakui saat piutang timbul. Kesalahan umum: mencatatnya sebagai pendapatan baru sehingga ekuitas ikut naik dua kali." },
    { q: "Perusahaan membayar angsuran utang bank Rp10.000.000 plus bunga Rp1.000.000 secara tunai. Pengaruhnya adalah ...", options: ["Kas berkurang Rp11.000.000, utang bank berkurang Rp10.000.000, ekuitas berkurang Rp1.000.000", "Kas berkurang Rp11.000.000 dan utang bank berkurang Rp11.000.000", "Kas berkurang Rp10.000.000 dan ekuitas berkurang Rp1.000.000", "Utang bank berkurang Rp11.000.000 dan ekuitas bertambah Rp1.000.000"], answer: 0, solution: "1. Kas berkurang Rp11.000.000. 2. Utang Bank berkurang Rp10.000.000 (pokok). 3. Beban bunga Rp1.000.000 mengurangi ekuitas. Kesalahan umum: menganggap seluruh Rp11.000.000 mengurangi utang, padahal bunga adalah beban." },
    { q: "Pemilik mengambil kas Rp2.000.000 untuk keperluan pribadi. Pengaruhnya terhadap persamaan dasar adalah ...", options: ["Kas berkurang dan utang berkurang Rp2.000.000", "Hanya komposisi aset yang berubah", "Aset (kas) berkurang dan ekuitas berkurang Rp2.000.000", "Kas berkurang dan pendapatan berkurang"], answer: 2, solution: "1. Kas (aset) berkurang Rp2.000.000. 2. Prive mengurangi ekuitas sebesar Rp2.000.000. 3. Kedua sisi turun sama besar. Kesalahan umum: mencatat prive sebagai beban operasional perusahaan." },
    { q: "Perusahaan membayar sewa Rp12.000.000 untuk 12 bulan ke depan secara tunai. Pengaruhnya adalah ...", options: ["Kas berkurang dan ekuitas berkurang Rp12.000.000", "Kas berkurang dan sewa dibayar di muka bertambah Rp12.000.000, total aset tetap", "Aset berkurang Rp12.000.000 dan liabilitas bertambah", "Kas berkurang dan utang sewa bertambah"], answer: 1, solution: "1. Kas (aset) berkurang Rp12.000.000. 2. Sewa Dibayar di Muka (aset) bertambah Rp12.000.000. 3. Keduanya aset, jadi total aset tetap; beban baru diakui bertahap lewat penyesuaian. Kesalahan umum: langsung mencatat seluruhnya sebagai beban sehingga ekuitas turun Rp12.000.000." },
    { q: "Perusahaan menerima uang muka jasa Rp5.000.000 secara tunai dari pelanggan. Pengaruhnya adalah ...", options: ["Kas bertambah dan pendapatan bertambah Rp5.000.000", "Kas bertambah dan pendapatan diterima di muka (liabilitas) bertambah Rp5.000.000", "Hanya komposisi aset yang berubah", "Kas bertambah dan modal bertambah"], answer: 1, solution: "1. Kas (aset) bertambah Rp5.000.000. 2. Jasa belum dikerjakan sehingga timbul Pendapatan Diterima di Muka (liabilitas) Rp5.000.000, bukan pendapatan. 3. Pendapatan baru diakui setelah jasa dikerjakan. Kesalahan umum: langsung mengakui sebagai pendapatan periode ini." },
    { q: "Perusahaan membeli gedung Rp200.000.000 dengan membayar tunai Rp50.000.000 dan sisanya dengan utang bank. Pengaruhnya adalah ...", options: ["Aset bertambah bersih Rp150.000.000 dan liabilitas bertambah Rp150.000.000", "Aset bertambah Rp200.000.000 dan ekuitas bertambah Rp200.000.000", "Total aset tetap dan liabilitas bertambah Rp150.000.000", "Aset berkurang Rp50.000.000 dan liabilitas bertambah Rp150.000.000"], answer: 0, solution: "1. Gedung (aset) bertambah Rp200.000.000, Kas (aset) berkurang Rp50.000.000, sehingga aset neto bertambah Rp150.000.000. 2. Utang Bank (liabilitas) bertambah Rp150.000.000. 3. Kenaikan aset neto diimbangi kenaikan liabilitas. Kesalahan umum: hanya melihat kas yang keluar lalu menyimpulkan aset berkurang." },
    { q: "Akun Beban Depresiasi memiliki saldo normal di sisi ...", options: ["Kredit", "Debit", "Nol", "Tergantung jenis asetnya"], answer: 1, solution: "1. Beban depresiasi adalah akun beban yang mengurangi ekuitas. 2. Semua akun beban bersaldo normal debit. Kesalahan umum: mengira beban depresiasi bersaldo kredit karena pasangannya (akumulasi depresiasi) bersaldo kredit." },
    { q: "Saldo normal akun Akumulasi Depresiasi adalah ...", options: ["Debit", "Kredit", "Nol", "Tergantung umurnya"], answer: 1, solution: "1. Akumulasi depresiasi adalah akun kontra aset. 2. Akun kontra mengurangi akun berpasangannya (aset bersaldo debit), sehingga ia bersaldo normal kredit. Kesalahan umum: mengira akumulasi depresiasi bersaldo debit karena berkaitan dengan aset." },
    { q: "Akun Pendapatan Diterima di Muka memiliki saldo normal di sisi ...", options: ["Debit", "Kredit", "Nol", "Tergantung jenis jasanya"], answer: 1, solution: "1. Pendapatan diterima di muka adalah kewajiban (liabilitas) karena jasa belum dikerjakan. 2. Liabilitas bersaldo normal kredit. Kesalahan umum: mengira akun ini bersaldo debit karena namanya mengandung kata pendapatan." },
    { q: "Saldo normal akun Modal Pemilik adalah ...", options: ["Debit", "Kredit", "Nol", "Tergantung labanya"], answer: 1, solution: "1. Modal adalah bagian dari ekuitas. 2. Ekuitas bertambah di sisi kredit, jadi saldo normal modal adalah kredit. Kesalahan umum: mendebet modal saat ada setoran dengan logika kas bertambah di debit." },
    { q: "Akun Piutang Usaha memiliki saldo normal di sisi ...", options: ["Kredit", "Nol", "Debit", "Tergantung pelunasannya"], answer: 2, solution: "1. Piutang usaha adalah aset (hak menagih). 2. Aset bersaldo normal debit. Kesalahan umum: mengira piutang bersaldo kredit karena berkaitan dengan pendapatan yang bersaldo kredit." },
    { q: "Saldo normal akun Sewa Dibayar di Muka adalah ...", options: ["Debit", "Kredit", "Nol", "Tergantung periodenya"], answer: 0, solution: "1. Sewa dibayar di muka adalah aset (hak memakai). 2. Aset bersaldo normal debit. Kesalahan umum: mengira akun ini beban sehingga langsung dihabiskan, atau mencatatnya di sisi kredit." },
    { q: "Akun Utang Gaji memiliki saldo normal di sisi ...", options: ["Debit", "Kredit", "Nol", "Tergantung jumlah karyawannya"], answer: 1, solution: "1. Utang gaji adalah kewajiban (liabilitas). 2. Liabilitas bersaldo normal kredit. Kesalahan umum: mengira utang gaji adalah beban sehingga mencatatnya bersaldo debit." },
    { q: "Untuk menambah akun Tanah, pencatatan dilakukan di sisi ...", options: ["Kredit", "Sisi mana pun boleh", "Debit", "Tergantung nilainya"], answer: 2, solution: "1. Tanah adalah aset dengan saldo normal debit. 2. Penambahan aset dicatat di sisi debit. Kesalahan umum: mengkredit tanah karena kas yang dibayarkan dicatat di kredit." },
    { q: "Untuk mengurangi akun Utang Usaha, pencatatan dilakukan di sisi ...", options: ["Kredit", "Debit", "Tergantung jumlahnya", "Sisi mana pun boleh"], answer: 1, solution: "1. Utang usaha adalah liabilitas bersaldo normal kredit. 2. Pengurangan liabilitas dicatat di sisi berlawanan, yaitu debit. Kesalahan umum: mengkredit utang saat membayarnya dengan alasan membayar itu pengeluaran." },
    { q: "Untuk mengurangi akun Kas, pencatatan dilakukan di sisi ...", options: ["Debit", "Kredit", "Tergantung jumlahnya", "Sisi mana pun boleh"], answer: 1, solution: "1. Kas adalah aset bersaldo normal debit. 2. Pengurangan aset dicatat di sisi berlawanan, yaitu kredit. Kesalahan umum: mendebet kas saat membayar dengan alasan kas yang keluar harus dicatat dulu." },
    { q: "Akun Pendapatan Bunga memiliki saldo normal di sisi ...", options: ["Debit", "Nol", "Kredit", "Tergantung banknya"], answer: 2, solution: "1. Pendapatan bunga menambah ekuitas. 2. Semua akun pendapatan bersaldo normal kredit. Kesalahan umum: mendebet pendapatan bunga dengan alasan kas (yang bersaldo debit) bertambah." },
    { q: "Saldo normal akun Beban Perlengkapan adalah ...", options: ["Kredit", "Debit", "Nol", "Tergantung sisanya"], answer: 1, solution: "1. Beban perlengkapan adalah akun beban. 2. Semua beban bersaldo normal debit. Kesalahan umum: mengira beban perlengkapan bersaldo kredit karena perlengkapannya sendiri berkurang di kredit saat penyesuaian." },
    { q: "Berikut ini akun yang bersaldo normal debit, KECUALI ...", options: ["Kas", "Piutang Usaha", "Utang Pajak", "Peralatan"], answer: 2, solution: "1. Kas, piutang usaha, dan peralatan adalah aset bersaldo normal debit. 2. Utang pajak adalah liabilitas yang bersaldo normal kredit. Kesalahan umum: mengira semua akun yang sering muncul di sisi debit jurnal bersaldo debit." },
    { q: "Berikut ini akun yang bersaldo normal kredit, KECUALI ...", options: ["Modal Pemilik", "Utang Bank", "Peralatan", "Pendapatan Sewa"], answer: 2, solution: "1. Modal, utang bank, dan pendapatan sewa bersaldo normal kredit. 2. Peralatan adalah aset yang bersaldo normal debit. Kesalahan umum: mengira peralatan bersaldo kredit karena sering dibeli secara kredit." },
    { q: "Dibeli gedung Rp250.000.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Kas Rp250.000.000 – Kredit Gedung Rp250.000.000", "Debit Gedung Rp250.000.000 – Kredit Kas Rp250.000.000", "Debit Gedung Rp250.000.000 – Kredit Utang Usaha Rp250.000.000", "Debit Beban Gedung Rp250.000.000 – Kredit Kas Rp250.000.000"], answer: 1, solution: "1. Gedung (aset) bertambah Rp250.000.000 → debit. 2. Kas (aset) berkurang Rp250.000.000 → kredit. 3. Jurnal: Debit Gedung, Kredit Kas. Kesalahan umum: mencatat gedung sebagai beban, atau mengkredit utang padahal dibayar tunai." },
    { q: "Diterima pinjaman bank Rp100.000.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Kas Rp100.000.000 – Kredit Utang Bank Rp100.000.000", "Debit Utang Bank Rp100.000.000 – Kredit Kas Rp100.000.000", "Debit Kas Rp100.000.000 – Kredit Modal Rp100.000.000", "Debit Modal Rp100.000.000 – Kredit Kas Rp100.000.000"], answer: 0, solution: "1. Kas (aset) bertambah Rp100.000.000 → debit. 2. Utang Bank (liabilitas) bertambah Rp100.000.000 → kredit. 3. Jurnal: Debit Kas, Kredit Utang Bank. Kesalahan umum: mencatat pinjaman sebagai penambahan modal atau pendapatan." },
    { q: "Dibayar beban iklan Rp1.500.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Kas Rp1.500.000 – Kredit Beban Iklan Rp1.500.000", "Debit Beban Iklan Rp1.500.000 – Kredit Kas Rp1.500.000", "Debit Beban Iklan Rp1.500.000 – Kredit Utang Usaha Rp1.500.000", "Debit Iklan Dibayar di Muka Rp1.500.000 – Kredit Kas Rp1.500.000"], answer: 1, solution: "1. Beban Iklan bertambah Rp1.500.000 → debit. 2. Kas berkurang Rp1.500.000 → kredit. 3. Jurnal: Debit Beban Iklan, Kredit Kas. Kesalahan umum: membalik sisi atau mencatatnya sebagai iklan dibayar di muka padahal manfaatnya sudah dinikmati periode ini." },
    { q: "Diterima pendapatan jasa Rp9.000.000, dengan rincian Rp4.000.000 tunai dan Rp5.000.000 belum dibayar pelanggan. Jurnal yang benar adalah ...", options: ["Debit Kas Rp9.000.000 – Kredit Pendapatan Jasa Rp9.000.000", "Debit Kas Rp4.000.000, Debit Piutang Usaha Rp5.000.000 – Kredit Pendapatan Jasa Rp9.000.000", "Debit Piutang Usaha Rp9.000.000 – Kredit Kas Rp4.000.000 – Kredit Pendapatan Jasa Rp5.000.000", "Debit Kas Rp4.000.000 – Kredit Piutang Usaha Rp5.000.000 – Kredit Pendapatan Jasa Rp9.000.000"], answer: 1, solution: "1. Kas bertambah Rp4.000.000 → debit; Piutang Usaha bertambah Rp5.000.000 → debit. 2. Pendapatan Jasa bertambah Rp9.000.000 → kredit. 3. Total debit Rp9.000.000 = total kredit Rp9.000.000, jurnal majemuk ini seimbang. Kesalahan umum: hanya mencatat kas Rp4.000.000 dan mengabaikan piutangnya." },
    { q: "Dibayar utang usaha Rp12.000.000 secara tunai. Jurnal umum yang benar adalah ...", options: ["Debit Utang Usaha Rp12.000.000 – Kredit Kas Rp12.000.000", "Debit Kas Rp12.000.000 – Kredit Utang Usaha Rp12.000.000", "Debit Beban Utang Rp12.000.000 – Kredit Kas Rp12.000.000", "Debit Utang Usaha Rp12.000.000 – Kredit Modal Rp12.000.000"], answer: 0, solution: "1. Utang Usaha (liabilitas) berkurang Rp12.000.000 → debit. 2. Kas berkurang Rp12.000.000 → kredit. 3. Jurnal: Debit Utang Usaha, Kredit Kas. Kesalahan umum: mencatat pembayaran utang sebagai beban." },
    { q: "Pemilik menyetorkan kendaraan senilai Rp80.000.000 sebagai tambahan modal. Jurnal yang benar adalah ...", options: ["Debit Kas Rp80.000.000 – Kredit Modal Rp80.000.000", "Debit Kendaraan Rp80.000.000 – Kredit Modal Rp80.000.000", "Debit Modal Rp80.000.000 – Kredit Kendaraan Rp80.000.000", "Debit Kendaraan Rp80.000.000 – Kredit Kas Rp80.000.000"], answer: 1, solution: "1. Kendaraan (aset) bertambah Rp80.000.000 → debit. 2. Modal (ekuitas) bertambah Rp80.000.000 → kredit. 3. Jurnal: Debit Kendaraan, Kredit Modal. Kesalahan umum: mendebet kas padahal yang disetor bukan uang tunai." },
    { q: "Diterima pelunasan piutang Rp6.500.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Kas Rp6.500.000 – Kredit Pendapatan Jasa Rp6.500.000", "Debit Piutang Usaha Rp6.500.000 – Kredit Kas Rp6.500.000", "Debit Kas Rp6.500.000 – Kredit Piutang Usaha Rp6.500.000", "Debit Kas Rp6.500.000 – Kredit Utang Usaha Rp6.500.000"], answer: 2, solution: "1. Kas bertambah Rp6.500.000 → debit. 2. Piutang Usaha berkurang Rp6.500.000 → kredit. 3. Ini bukan pendapatan baru — pendapatan sudah dicatat saat piutang timbul. Kesalahan umum: mengkredit pendapatan jasa sehingga pendapatan tercatat dua kali." },
    { q: "Dibayar sewa Rp24.000.000 untuk 2 tahun ke depan secara tunai. Jurnal yang benar adalah ...", options: ["Debit Beban Sewa Rp24.000.000 – Kredit Kas Rp24.000.000", "Debit Sewa Dibayar di Muka Rp24.000.000 – Kredit Kas Rp24.000.000", "Debit Kas Rp24.000.000 – Kredit Sewa Dibayar di Muka Rp24.000.000", "Debit Sewa Dibayar di Muka Rp24.000.000 – Kredit Utang Sewa Rp24.000.000"], answer: 1, solution: "1. Sewa Dibayar di Muka (aset) bertambah Rp24.000.000 → debit. 2. Kas berkurang Rp24.000.000 → kredit. 3. Beban diakui bertahap melalui jurnal penyesuaian. Kesalahan umum: langsung mencatat seluruhnya sebagai beban sewa periode ini." },
    { q: "Diterima uang muka jasa Rp10.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Kas Rp10.000.000 – Kredit Pendapatan Jasa Rp10.000.000", "Debit Kas Rp10.000.000 – Kredit Pendapatan Diterima di Muka Rp10.000.000", "Debit Pendapatan Diterima di Muka Rp10.000.000 – Kredit Kas Rp10.000.000", "Debit Piutang Usaha Rp10.000.000 – Kredit Pendapatan Jasa Rp10.000.000"], answer: 1, solution: "1. Kas bertambah Rp10.000.000 → debit. 2. Jasa belum dikerjakan → timbul liabilitas Pendapatan Diterima di Muka Rp10.000.000 → kredit. 3. Jurnal: Debit Kas, Kredit Pendapatan Diterima di Muka. Kesalahan umum: langsung mengkredit pendapatan jasa." },
    { q: "Pemilik mengambil perlengkapan Rp500.000 untuk keperluan pribadi. Jurnal yang benar adalah ...", options: ["Debit Prive Rp500.000 – Kredit Perlengkapan Rp500.000", "Debit Beban Perlengkapan Rp500.000 – Kredit Perlengkapan Rp500.000", "Debit Perlengkapan Rp500.000 – Kredit Prive Rp500.000", "Debit Prive Rp500.000 – Kredit Kas Rp500.000"], answer: 0, solution: "1. Prive bertambah Rp500.000 → debit. 2. Perlengkapan (aset) berkurang Rp500.000 → kredit. 3. Prive tidak harus berupa kas — bisa berupa aset lain. Kesalahan umum: mengkredit kas padahal kas tidak berkurang." },
    { q: "Diterima pendapatan sewa Rp4.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Pendapatan Sewa Rp4.000.000 – Kredit Kas Rp4.000.000", "Debit Kas Rp4.000.000 – Kredit Pendapatan Sewa Rp4.000.000", "Debit Kas Rp4.000.000 – Kredit Modal Rp4.000.000", "Debit Piutang Sewa Rp4.000.000 – Kredit Pendapatan Sewa Rp4.000.000"], answer: 1, solution: "1. Kas bertambah Rp4.000.000 → debit. 2. Pendapatan Sewa bertambah Rp4.000.000 → kredit. 3. Jurnal: Debit Kas, Kredit Pendapatan Sewa. Kesalahan umum: mendebet pendapatan atau mencatatnya sebagai penambahan modal." },
    { q: "Dibeli perlengkapan Rp4.000.000 dengan membayar tunai Rp1.000.000 dan sisanya kredit. Jurnal yang benar adalah ...", options: ["Debit Perlengkapan Rp4.000.000 – Kredit Kas Rp4.000.000", "Debit Perlengkapan Rp4.000.000 – Kredit Kas Rp1.000.000 – Kredit Utang Usaha Rp3.000.000", "Debit Perlengkapan Rp1.000.000 – Kredit Kas Rp1.000.000", "Debit Perlengkapan Rp4.000.000 – Kredit Utang Usaha Rp4.000.000"], answer: 1, solution: "1. Perlengkapan bertambah Rp4.000.000 → debit. 2. Kas berkurang Rp1.000.000 → kredit; Utang Usaha bertambah Rp3.000.000 → kredit. 3. Total debit Rp4.000.000 = total kredit Rp4.000.000. Kesalahan umum: hanya mencatat bagian tunai Rp1.000.000 dan mengabaikan utangnya." },
    { q: "Dibayar beban gaji Rp7.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Kas Rp7.000.000 – Kredit Beban Gaji Rp7.000.000", "Debit Beban Gaji Rp7.000.000 – Kredit Utang Gaji Rp7.000.000", "Debit Beban Gaji Rp7.000.000 – Kredit Kas Rp7.000.000", "Debit Utang Gaji Rp7.000.000 – Kredit Kas Rp7.000.000"], answer: 2, solution: "1. Beban Gaji bertambah Rp7.000.000 → debit. 2. Kas berkurang Rp7.000.000 → kredit. 3. Jurnal: Debit Beban Gaji, Kredit Kas. Kesalahan umum: mengkredit utang gaji padahal gaji langsung dibayar tunai." },
    { q: "Diterima pendapatan bunga Rp800.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Kas Rp800.000 – Kredit Pendapatan Bunga Rp800.000", "Debit Pendapatan Bunga Rp800.000 – Kredit Kas Rp800.000", "Debit Kas Rp800.000 – Kredit Pendapatan Jasa Rp800.000", "Debit Piutang Bunga Rp800.000 – Kredit Kas Rp800.000"], answer: 0, solution: "1. Kas bertambah Rp800.000 → debit. 2. Pendapatan Bunga bertambah Rp800.000 → kredit. 3. Jurnal: Debit Kas, Kredit Pendapatan Bunga. Kesalahan umum: mencatatnya sebagai pendapatan jasa." },
    { q: "Dibeli tanah Rp120.000.000 dengan membayar tunai Rp20.000.000 dan sisanya kredit. Jurnal yang benar adalah ...", options: ["Debit Tanah Rp120.000.000 – Kredit Kas Rp120.000.000", "Debit Tanah Rp20.000.000 – Kredit Kas Rp20.000.000", "Debit Tanah Rp120.000.000 – Kredit Kas Rp20.000.000 – Kredit Utang Usaha Rp100.000.000", "Debit Tanah Rp100.000.000 – Kredit Utang Usaha Rp100.000.000"], answer: 2, solution: "1. Tanah bertambah Rp120.000.000 → debit. 2. Kas berkurang Rp20.000.000 → kredit; Utang Usaha bertambah Rp100.000.000 → kredit. 3. Total debit = total kredit = Rp120.000.000. Kesalahan umum: hanya menjurnal bagian kredit Rp100.000.000." },
    { q: "Perusahaan dagang membeli barang dagang Rp15.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Pembelian Rp15.000.000 – Kredit Kas Rp15.000.000", "Debit Persediaan Barang Dagang Rp15.000.000 – Kredit Kas Rp15.000.000", "Debit Kas Rp15.000.000 – Kredit Persediaan Barang Dagang Rp15.000.000", "Debit Beban Pokok Rp15.000.000 – Kredit Kas Rp15.000.000"], answer: 1, solution: "1. Persediaan Barang Dagang (aset) bertambah Rp15.000.000 → debit. 2. Kas berkurang Rp15.000.000 → kredit. 3. Jurnal: Debit Persediaan Barang Dagang, Kredit Kas. Kesalahan umum: langsung mencatat sebagai beban/harga pokok padahal barang belum terjual." },
    { q: "Perusahaan dagang menjual barang dagang Rp10.000.000 secara tunai (harga pokok Rp6.000.000). Jurnal untuk mencatat penjualannya adalah ...", options: ["Debit Kas Rp10.000.000 – Kredit Penjualan Rp10.000.000", "Debit Kas Rp6.000.000 – Kredit Penjualan Rp6.000.000", "Debit Penjualan Rp10.000.000 – Kredit Kas Rp10.000.000", "Debit Kas Rp10.000.000 – Kredit Persediaan Barang Dagang Rp10.000.000"], answer: 0, solution: "1. Kas bertambah Rp10.000.000 → debit. 2. Penjualan bertambah Rp10.000.000 → kredit (dicatat sebesar harga jual, bukan harga pokok). 3. Jurnal harga pokok dibuat terpisah: Debit HPP Rp6.000.000, Kredit Persediaan Rp6.000.000. Kesalahan umum: mencatat penjualan sebesar harga pokok Rp6.000.000." },
    { q: "Perusahaan mengembalikan barang dagang Rp2.000.000 ke pemasok (pembelian semula kredit). Jurnal yang benar adalah ...", options: ["Debit Utang Usaha Rp2.000.000 – Kredit Retur Pembelian Rp2.000.000", "Debit Retur Pembelian Rp2.000.000 – Kredit Utang Usaha Rp2.000.000", "Debit Kas Rp2.000.000 – Kredit Retur Pembelian Rp2.000.000", "Debit Utang Usaha Rp2.000.000 – Kredit Kas Rp2.000.000"], answer: 0, solution: "1. Utang Usaha berkurang Rp2.000.000 → debit. 2. Retur Pembelian (pengurang pembelian) bertambah Rp2.000.000 → kredit. 3. Jurnal: Debit Utang Usaha, Kredit Retur Pembelian. Kesalahan umum: membalik sisi atau mengkredit kas padahal tidak ada kas yang diterima." },
    { q: "Diterima pendapatan komisi Rp2.500.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Kas Rp2.500.000 – Kredit Pendapatan Komisi Rp2.500.000", "Debit Pendapatan Komisi Rp2.500.000 – Kredit Kas Rp2.500.000", "Debit Kas Rp2.500.000 – Kredit Piutang Komisi Rp2.500.000", "Debit Kas Rp2.500.000 – Kredit Modal Rp2.500.000"], answer: 0, solution: "1. Kas bertambah Rp2.500.000 → debit. 2. Pendapatan Komisi bertambah Rp2.500.000 → kredit. 3. Jurnal: Debit Kas, Kredit Pendapatan Komisi. Kesalahan umum: mendebet pendapatan komisi." },
    { q: "Dibayar premi asuransi Rp3.600.000 untuk 12 bulan ke depan secara tunai. Jurnal yang benar adalah ...", options: ["Debit Beban Asuransi Rp3.600.000 – Kredit Kas Rp3.600.000", "Debit Asuransi Dibayar di Muka Rp3.600.000 – Kredit Kas Rp3.600.000", "Debit Kas Rp3.600.000 – Kredit Asuransi Dibayar di Muka Rp3.600.000", "Debit Asuransi Dibayar di Muka Rp3.600.000 – Kredit Utang Asuransi Rp3.600.000"], answer: 1, solution: "1. Asuransi Dibayar di Muka (aset) bertambah Rp3.600.000 → debit. 2. Kas berkurang Rp3.600.000 → kredit. 3. Beban diakui tiap bulan lewat penyesuaian sebesar Rp300.000. Kesalahan umum: langsung mencatat seluruhnya sebagai beban asuransi." },
    { q: "Dibayar beban transportasi Rp750.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Kas Rp750.000 – Kredit Beban Transportasi Rp750.000", "Debit Beban Transportasi Rp750.000 – Kredit Kas Rp750.000", "Debit Beban Transportasi Rp750.000 – Kredit Utang Usaha Rp750.000", "Debit Modal Rp750.000 – Kredit Kas Rp750.000"], answer: 1, solution: "1. Beban Transportasi bertambah Rp750.000 → debit. 2. Kas berkurang Rp750.000 → kredit. 3. Jurnal: Debit Beban Transportasi, Kredit Kas. Kesalahan umum: membalik sisi debit dan kredit." },
    { q: "Pemilik menyetorkan modal berupa kas Rp25.000.000 dan peralatan Rp10.000.000. Jurnal yang benar adalah ...", options: ["Debit Kas Rp25.000.000, Debit Peralatan Rp10.000.000 – Kredit Modal Rp35.000.000", "Debit Kas Rp35.000.000 – Kredit Modal Rp35.000.000", "Debit Modal Rp35.000.000 – Kredit Kas Rp25.000.000 – Kredit Peralatan Rp10.000.000", "Debit Kas Rp25.000.000 – Kredit Peralatan Rp10.000.000 – Kredit Modal Rp15.000.000"], answer: 0, solution: "1. Kas bertambah Rp25.000.000 → debit; Peralatan bertambah Rp10.000.000 → debit. 2. Modal bertambah Rp35.000.000 → kredit. 3. Total debit Rp35.000.000 = total kredit Rp35.000.000. Kesalahan umum: hanya mencatat setoran kas dan melupakan peralatannya." },
    { q: "Dibayar beban listrik dan air Rp1.200.000 secara tunai. Jurnal yang benar adalah ...", options: ["Debit Beban Listrik dan Air Rp1.200.000 – Kredit Kas Rp1.200.000", "Debit Kas Rp1.200.000 – Kredit Beban Listrik dan Air Rp1.200.000", "Debit Beban Listrik dan Air Rp1.200.000 – Kredit Utang Usaha Rp1.200.000", "Debit Utang Listrik Rp1.200.000 – Kredit Kas Rp1.200.000"], answer: 0, solution: "1. Beban Listrik dan Air bertambah Rp1.200.000 → debit. 2. Kas berkurang Rp1.200.000 → kredit. 3. Jurnal: Debit Beban Listrik dan Air, Kredit Kas. Kesalahan umum: mengkredit utang usaha padahal dibayar tunai." },
    { q: "Dibeli perlengkapan Rp5.000.000 secara tunai dengan diskon 10%. Jurnal yang benar adalah ...", options: ["Debit Perlengkapan Rp5.000.000 – Kredit Kas Rp5.000.000", "Debit Perlengkapan Rp5.000.000 – Kredit Kas Rp4.500.000 – Kredit Potongan Pembelian Rp500.000", "Debit Perlengkapan Rp4.500.000 – Kredit Kas Rp4.500.000", "Debit Kas Rp4.500.000 – Kredit Perlengkapan Rp4.500.000"], answer: 1, solution: "1. Perlengkapan dicatat sebesar harga bruto Rp5.000.000 → debit. 2. Kas yang dibayar = Rp5.000.000 − 10% = Rp4.500.000 → kredit; Potongan Pembelian Rp500.000 → kredit. 3. Total kredit Rp5.000.000 = total debit. Kesalahan umum: mencatat perlengkapan sebesar harga neto Rp4.500.000 dan mengabaikan potongannya." },
    { q: "Diterima tagihan listrik Rp900.000 yang akan dibayar bulan depan. Jurnal yang benar adalah ...", options: ["Debit Beban Listrik Rp900.000 – Kredit Kas Rp900.000", "Debit Beban Listrik Rp900.000 – Kredit Utang Usaha Rp900.000", "Tidak dijurnal karena belum dibayar", "Debit Utang Usaha Rp900.000 – Kredit Beban Listrik Rp900.000"], answer: 1, solution: "1. Beban Listrik sudah menjadi beban periode ini Rp900.000 → debit. 2. Belum dibayar → timbul Utang Usaha Rp900.000 → kredit. 3. Basis akrual mencatat beban saat terjadi, bukan saat dibayar. Kesalahan umum: tidak mencatat apa-apa dengan alasan belum ada kas yang keluar." },
    { q: "Beban gaji bulan ini Rp8.000.000, dibayar tunai Rp6.000.000 dan sisanya masih terutang. Jurnal yang benar adalah ...", options: ["Debit Beban Gaji Rp8.000.000 – Kredit Kas Rp8.000.000", "Debit Beban Gaji Rp6.000.000 – Kredit Kas Rp6.000.000", "Debit Beban Gaji Rp8.000.000 – Kredit Kas Rp6.000.000 – Kredit Utang Gaji Rp2.000.000", "Debit Beban Gaji Rp6.000.000, Debit Utang Gaji Rp2.000.000 – Kredit Kas Rp8.000.000"], answer: 2, solution: "1. Beban Gaji periode ini Rp8.000.000 → debit penuh. 2. Kas berkurang Rp6.000.000 → kredit; Utang Gaji bertambah Rp2.000.000 → kredit. 3. Total kredit Rp8.000.000 = total debit. Kesalahan umum: hanya mencatat Rp6.000.000 yang dibayar tunai." },
    { q: "Akun Utang Usaha bersaldo awal kredit Rp20.000.000, mutasi debit Rp8.000.000, mutasi kredit Rp5.000.000. Saldo akhirnya adalah ...", options: ["Rp17.000.000 (kredit)", "Rp23.000.000 (kredit)", "Rp33.000.000 (kredit)", "Rp7.000.000 (debit)"], answer: 0, solution: "1. Untuk akun bersaldo normal kredit: saldo akhir = saldo awal + mutasi kredit − mutasi debit. 2. Rp20.000.000 + Rp5.000.000 − Rp8.000.000 = Rp17.000.000 (kredit). Kesalahan umum: memakai rumus akun debit sehingga mendapat Rp23.000.000." },
    { q: "Akun Piutang Usaha bersaldo awal debit Rp12.000.000, mutasi debit Rp9.000.000, mutasi kredit Rp6.000.000. Saldo akhirnya adalah ...", options: ["Rp9.000.000 (debit)", "Rp15.000.000 (debit)", "Rp27.000.000 (debit)", "Rp3.000.000 (kredit)"], answer: 1, solution: "1. Untuk akun bersaldo normal debit: saldo akhir = saldo awal + mutasi debit − mutasi kredit. 2. Rp12.000.000 + Rp9.000.000 − Rp6.000.000 = Rp15.000.000 (debit). Kesalahan umum: menjumlahkan semua angka menjadi Rp27.000.000." },
    { q: "Akun Modal bersaldo awal kredit Rp40.000.000 dan ada setoran tambahan Rp15.000.000. Saldo akhirnya adalah ...", options: ["Rp25.000.000 (kredit)", "Rp55.000.000 (kredit)", "Rp40.000.000 (kredit)", "Rp15.000.000 (debit)"], answer: 1, solution: "1. Modal bersaldo normal kredit; setoran menambah modal di sisi kredit. 2. Rp40.000.000 + Rp15.000.000 = Rp55.000.000 (kredit). Kesalahan umum: mengurangkan setoran dari modal awal menjadi Rp25.000.000." },
    { q: "Akun Beban Sewa bersaldo awal nol, mutasi debit Rp6.000.000, dan tidak ada mutasi kredit. Saldo akhirnya adalah ...", options: ["Rp6.000.000 (kredit)", "Nol", "Rp6.000.000 (debit)", "Rp12.000.000 (debit)"], answer: 2, solution: "1. Beban bersaldo normal debit: saldo akhir = 0 + Rp6.000.000 − 0 = Rp6.000.000 (debit). 2. Akun beban umumnya mulai dari nol setiap periode. Kesalahan umum: menempatkan saldo beban di sisi kredit." },
    { q: "Akun Pendapatan Diterima di Muka bersaldo awal kredit Rp9.000.000, mutasi kredit Rp6.000.000, mutasi debit Rp4.000.000. Saldo akhirnya adalah ...", options: ["Rp11.000.000 (kredit)", "Rp19.000.000 (kredit)", "Rp7.000.000 (kredit)", "Rp11.000.000 (debit)"], answer: 0, solution: "1. Untuk akun bersaldo normal kredit: saldo akhir = saldo awal + mutasi kredit − mutasi debit. 2. Rp9.000.000 + Rp6.000.000 − Rp4.000.000 = Rp11.000.000 (kredit). Kesalahan umum: memakai rumus sisi debit sehingga mendapat Rp7.000.000." },
    { q: "Akun Utang Bank bersaldo awal kredit Rp100.000.000, mutasi debit Rp25.000.000, mutasi kredit Rp10.000.000. Saldo akhirnya adalah ...", options: ["Rp115.000.000 (kredit)", "Rp85.000.000 (kredit)", "Rp65.000.000 (kredit)", "Rp135.000.000 (debit)"], answer: 1, solution: "1. Saldo akhir = Rp100.000.000 + Rp10.000.000 − Rp25.000.000 = Rp85.000.000 (kredit). 2. Mutasi debit mengurangi utang (angsuran), mutasi kredit menambah utang. Kesalahan umum: menjumlahkan semua mutasi menjadi Rp135.000.000." },
    { q: "Akun Pendapatan Jasa bersaldo awal kredit nol, mutasi kredit Rp45.000.000, mutasi debit Rp3.000.000. Saldo akhirnya adalah ...", options: ["Rp48.000.000 (kredit)", "Rp42.000.000 (kredit)", "Rp45.000.000 (kredit)", "Rp42.000.000 (debit)"], answer: 1, solution: "1. Saldo akhir = 0 + Rp45.000.000 − Rp3.000.000 = Rp42.000.000 (kredit). 2. Mutasi debit pada akun pendapatan biasanya koreksi/retur. Kesalahan umum: mengabaikan mutasi debit sehingga mendapat Rp45.000.000." },
    { q: "Akun Perlengkapan bersaldo awal debit Rp5.000.000, mutasi debit Rp2.000.000, mutasi kredit Rp4.000.000. Saldo akhirnya adalah ...", options: ["Rp11.000.000 (debit)", "Rp3.000.000 (debit)", "Rp7.000.000 (debit)", "Rp1.000.000 (kredit)"], answer: 1, solution: "1. Saldo akhir = Rp5.000.000 + Rp2.000.000 − Rp4.000.000 = Rp3.000.000 (debit). 2. Mutasi kredit pada perlengkapan biasanya pemakaian yang dipindah ke beban. Kesalahan umum: menjumlahkan semuanya menjadi Rp11.000.000." },
    { q: "Sebuah neraca saldo memuat: Kas (debit) Rp10.000.000, Utang Usaha (kredit) Rp6.000.000, dan Modal (kredit) Rp4.000.000. Kondisinya adalah ...", options: ["Seimbang, total debit Rp10.000.000 = total kredit Rp10.000.000", "Tidak seimbang, selisih Rp4.000.000", "Tidak seimbang, selisih Rp6.000.000", "Seimbang, total debit Rp20.000.000 = total kredit Rp20.000.000"], answer: 0, solution: "1. Total sisi debit = Rp10.000.000. 2. Total sisi kredit = Rp6.000.000 + Rp4.000.000 = Rp10.000.000. 3. Keduanya sama, jadi neraca saldo seimbang. Kesalahan umum: menjumlahkan semua angka menjadi Rp20.000.000 tanpa memisahkan sisi." },
    { q: "Total sisi debit neraca saldo Rp85.000.000 sedangkan total sisi kredit Rp83.000.000. Kesimpulan yang tepat adalah ...", options: ["Neraca saldo seimbang karena selisihnya kecil", "Ada kesalahan pencatatan sebesar selisih Rp2.000.000 yang harus ditelusuri", "Perusahaan mengalami kerugian Rp2.000.000", "Modal harus dikurangi Rp2.000.000 agar seimbang"], answer: 1, solution: "1. Selisih = Rp85.000.000 − Rp83.000.000 = Rp2.000.000. 2. Selisih sekecil apa pun berarti ada kesalahan mekanis (salah sisi, salah angka, atau lupa posting). 3. Selisih harus ditelusuri, bukan ditutup dengan akun fiktif. Kesalahan umum: mengabaikan selisih kecil atau menganggapnya sebagai kerugian." },
    { q: "Dalam neraca saldo, akun Modal Pemilik ternyata bersaldo debit. Hal ini menunjukkan ...", options: ["Kondisi normal karena modal bisa di sisi mana pun", "Kemungkinan kesalahan pencatatan yang perlu ditelusuri", "Bukti perusahaan sangat merugi", "Modal telah disetor penuh"], answer: 1, solution: "1. Modal bersaldo normal kredit. 2. Saldo debit adalah saldo abnormal yang menandakan kemungkinan salah jurnal atau salah posting. 3. Perlu ditelusuri ke jurnal sumbernya. Kesalahan umum: menganggapnya normal atau langsung menghapus akunnya." },
    { q: "Fungsi utama neraca saldo adalah ...", options: ["Menghitung laba bersih perusahaan", "Memeriksa kesamaan total debit dan kredit semua akun buku besar sebelum menyusun laporan keuangan", "Mencatat transaksi harian perusahaan", "Menentukan harga jual produk"], answer: 1, solution: "1. Neraca saldo meringkas seluruh saldo akun buku besar. 2. Fungsinya memastikan total debit sama dengan total kredit sebagai uji awal ketepatan pembukuan. 3. Neraca saldo yang seimbang menjadi dasar menyusun laporan keuangan. Kesalahan umum: mengira neraca saldo berfungsi menghitung laba bersih." },
    { q: "Akun-akun berikut ikut dimasukkan ke dalam neraca saldo, KECUALI ...", options: ["Kas", "Pendapatan Jasa", "Beban Gaji", "Tidak ada, semua akun buku besar dimasukkan"], answer: 3, solution: "1. Neraca saldo memuat seluruh akun buku besar, baik akun riil (aset, liabilitas, ekuitas) maupun akun nominal (pendapatan, beban). 2. Jadi kas, pendapatan jasa, dan beban gaji semuanya dimasukkan. Kesalahan umum: mengira hanya akun neraca yang dimasukkan." },
    { q: "Jika total debit sama dengan total kredit dalam neraca saldo, maka ...", options: ["Pembukuan dipastikan 100% bebas kesalahan", "Kemungkinan masih ada kesalahan yang tidak memengaruhi keseimbangan, seperti salah akun atau lupa menjurnal", "Laporan keuangan pasti sudah benar", "Tidak perlu lagi membuat jurnal penyesuaian"], answer: 1, solution: "1. Neraca saldo yang seimbang hanya membuktikan total debit = total kredit. 2. Kesalahan seperti menjurnal ke akun yang salah, lupa mencatat transaksi, atau salah jumlah yang sama di kedua sisi tidak terdeteksi. 3. Keseimbangan adalah syarat perlu, bukan syarat cukup. Kesalahan umum: mengira neraca saldo seimbang berarti tidak ada kesalahan sama sekali." },
    { q: "Dalam neraca saldo, akun Kas ternyata bersaldo kredit. Hal ini menunjukkan ...", options: ["Kondisi yang normal untuk akun kas", "Kemungkinan kesalahan pencatatan atau kas negatif (overdraft) yang perlu ditelusuri", "Bukti perusahaan sangat likuid", "Kas telah disetor ke bank"], answer: 1, solution: "1. Kas bersaldo normal debit. 2. Saldo kredit berarti kas negatif — kemungkinan salah catat atau penarikan melebihi saldo (overdraft). 3. Harus ditelusuri, bukan dibiarkan. Kesalahan umum: menganggap saldo kredit pada kas sebagai hal biasa." },
    { q: "Urutan penyajian akun dalam neraca saldo umumnya mengikuti ...", options: ["Urutan abjad nama akun", "Urutan akun dalam buku besar: aset, liabilitas, ekuitas, pendapatan, beban", "Urutan besarnya saldo dari terbesar", "Urutan tanggal transaksi"], answer: 1, solution: "1. Neraca saldo disusun mengikuti nomor/urutan akun dalam buku besar (chart of accounts). 2. Urutannya: aset, liabilitas, ekuitas, pendapatan, lalu beban. 3. Urutan ini memudahkan penyusunan laporan keuangan. Kesalahan umum: menyusun berdasarkan abjad atau besarnya saldo." },
    { q: "Total sisi debit Rp154.000.000 dan total sisi kredit Rp145.000.000. Selisih Rp9.000.000 yang habis dibagi 9 mengindikasikan kemungkinan ...", options: ["Lupa menjurnal satu transaksi", "Kesalahan angka terbalik (transposisi), misalnya Rp45.000 dicatat Rp54.000", "Salah menggolongkan akun", "Perusahaan mengalami kerugian"], answer: 1, solution: "1. Selisih = Rp154.000.000 − Rp145.000.000 = Rp9.000.000. 2. Selisih yang habis dibagi 9 adalah ciri khas kesalahan transposisi — dua digit angka tertukar, misalnya 45 menjadi 54 (selisih 9). 3. Telusuri angka-angka yang digitnya mungkin tertukar. Kesalahan umum: langsung menganggap ada transaksi yang lupa dicatat." },
    { q: "Dalam neraca saldo, akun Prive bersaldo ...", options: ["Kredit", "Nol", "Debit", "Tergantung labanya"], answer: 2, solution: "1. Prive mengurangi ekuitas. 2. Pengurangan ekuitas dicatat di sisi debit, jadi prive bersaldo debit dalam neraca saldo. 3. Nanti saldo prive akan menutup ke akun modal. Kesalahan umum: menempatkan prive di sisi kredit karena mengira prive menambah sesuatu." },
    { q: "Dibayar premi asuransi Rp6.000.000 untuk 12 bulan. Pada akhir periode, asuransi yang sudah terpakai 4 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Asuransi Rp2.000.000 – Kredit Asuransi Dibayar di Muka Rp2.000.000", "Debit Asuransi Dibayar di Muka Rp6.000.000 – Kredit Beban Asuransi Rp6.000.000", "Debit Beban Asuransi Rp6.000.000 – Kredit Kas Rp6.000.000", "Debit Beban Asuransi Rp4.000.000 – Kredit Asuransi Dibayar di Muka Rp4.000.000"], answer: 0, solution: "1. Premi per bulan = Rp6.000.000 ÷ 12 = Rp500.000. 2. Terpakai 4 bulan → beban = 4 × Rp500.000 = Rp2.000.000. 3. Jurnal: Debit Beban Asuransi Rp2.000.000, Kredit Asuransi Dibayar di Muka Rp2.000.000. Kesalahan umum: menjurnal sisanya (Rp4.000.000) sebagai beban." },
    { q: "Dibayar sewa Rp18.000.000 untuk 18 bulan. Pada akhir periode, sewa yang sudah terpakai 5 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Sewa Dibayar di Muka Rp18.000.000 – Kredit Beban Sewa Rp18.000.000", "Debit Beban Sewa Rp5.000.000 – Kredit Sewa Dibayar di Muka Rp5.000.000", "Debit Beban Sewa Rp18.000.000 – Kredit Kas Rp18.000.000", "Debit Beban Sewa Rp13.000.000 – Kredit Sewa Dibayar di Muka Rp13.000.000"], answer: 1, solution: "1. Sewa per bulan = Rp18.000.000 ÷ 18 = Rp1.000.000. 2. Terpakai 5 bulan → beban = 5 × Rp1.000.000 = Rp5.000.000. 3. Jurnal: Debit Beban Sewa Rp5.000.000, Kredit Sewa Dibayar di Muka Rp5.000.000. Kesalahan umum: mencatat sisanya (Rp13.000.000) sebagai beban." },
    { q: "Diterima di muka pendapatan jasa Rp9.000.000 untuk 9 bulan pengerjaan. Pada akhir periode, jasa yang sudah dikerjakan 4 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Pendapatan Jasa Rp9.000.000 – Kredit Kas Rp9.000.000", "Debit Kas Rp4.000.000 – Kredit Pendapatan Diterima di Muka Rp4.000.000", "Debit Pendapatan Diterima di Muka Rp9.000.000 – Kredit Pendapatan Jasa Rp9.000.000", "Debit Pendapatan Diterima di Muka Rp4.000.000 – Kredit Pendapatan Jasa Rp4.000.000"], answer: 3, solution: "1. Jasa per bulan = Rp9.000.000 ÷ 9 = Rp1.000.000. 2. Sudah dikerjakan 4 bulan → pendapatan diakui = 4 × Rp1.000.000 = Rp4.000.000. 3. Jurnal: Debit Pendapatan Diterima di Muka Rp4.000.000, Kredit Pendapatan Jasa Rp4.000.000. Kesalahan umum: mengakui seluruh Rp9.000.000 sebagai pendapatan." },
    { q: "Perusahaan memiliki utang bank Rp60.000.000 dengan bunga 12% per tahun. Bunga bulan Desember belum dibayar sampai akhir periode. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Bunga Rp600.000 – Kredit Utang Bunga Rp600.000", "Debit Utang Bunga Rp600.000 – Kredit Kas Rp600.000", "Debit Beban Bunga Rp7.200.000 – Kredit Utang Bunga Rp7.200.000", "Tidak perlu jurnal karena belum dibayar"], answer: 0, solution: "1. Bunga 1 bulan = Rp60.000.000 × 12% × 1/12 = Rp600.000. 2. Bunga Desember sudah menjadi beban periode ini → Debit Beban Bunga Rp600.000, Kredit Utang Bunga Rp600.000. 3. Bunga setahun (Rp7.200.000) hanya dipakai jika akrualnya setahun. Kesalahan umum: tidak mencatat dengan alasan belum dibayar." },
    { q: "Bunga deposito Rp1.200.000 untuk bulan Desember belum diterima dari bank sampai akhir periode. Jurnal penyesuaiannya adalah ...", options: ["Debit Kas Rp1.200.000 – Kredit Pendapatan Bunga Rp1.200.000", "Debit Piutang Bunga Rp1.200.000 – Kredit Pendapatan Bunga Rp1.200.000", "Debit Pendapatan Bunga Rp1.200.000 – Kredit Piutang Bunga Rp1.200.000", "Tidak dijurnal sampai uang diterima"], answer: 1, solution: "1. Bunga Desember sudah menjadi hak perusahaan → pendapatan akrual Rp1.200.000. 2. Belum diterima → Debit Piutang Bunga, Kredit Pendapatan Bunga. 3. Basis akrual mengakui pendapatan saat dihasilkan. Kesalahan umum: mendebet kas padahal kas belum diterima." },
    { q: "Saldo awal perlengkapan Rp2.000.000, pembelian selama periode Rp3.000.000, dan hasil opname fisik menunjukkan sisa Rp1.200.000. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Perlengkapan Rp3.800.000 – Kredit Perlengkapan Rp3.800.000", "Debit Beban Perlengkapan Rp1.200.000 – Kredit Perlengkapan Rp1.200.000", "Debit Perlengkapan Rp3.800.000 – Kredit Beban Perlengkapan Rp3.800.000", "Debit Beban Perlengkapan Rp5.000.000 – Kredit Kas Rp5.000.000"], answer: 0, solution: "1. Perlengkapan tersedia = Rp2.000.000 + Rp3.000.000 = Rp5.000.000. 2. Terpakai = Rp5.000.000 − Rp1.200.000 = Rp3.800.000. 3. Jurnal: Debit Beban Perlengkapan Rp3.800.000, Kredit Perlengkapan Rp3.800.000. Kesalahan umum: menjurnal sisa Rp1.200.000 sebagai beban." },
    { q: "Gedung dibeli Rp200.000.000 dengan nilai sisa Rp20.000.000 dan umur manfaat 20 tahun. Jurnal penyesuaian depresiasi tahun ini adalah ...", options: ["Debit Beban Depresiasi Rp9.000.000 – Kredit Akumulasi Depresiasi Rp9.000.000", "Debit Beban Depresiasi Rp10.000.000 – Kredit Gedung Rp10.000.000", "Debit Akumulasi Depresiasi Rp9.000.000 – Kredit Beban Depresiasi Rp9.000.000", "Debit Beban Depresiasi Rp9.000.000 – Kredit Kas Rp9.000.000"], answer: 0, solution: "1. Depresiasi per tahun = (Rp200.000.000 − Rp20.000.000) ÷ 20 = Rp9.000.000. 2. Jurnal: Debit Beban Depresiasi Rp9.000.000, Kredit Akumulasi Depresiasi Rp9.000.000. Kesalahan umum: tidak mengurangkan nilai sisa sehingga mendapat Rp10.000.000, atau mengkredit langsung akun Gedung." },
    { q: "Beban gaji bulan Desember Rp6.000.000, baru dibayar Rp4.000.000 dan sisanya masih terutang. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Gaji Rp4.000.000 – Kredit Kas Rp4.000.000", "Debit Beban Gaji Rp6.000.000 – Kredit Kas Rp4.000.000 – Kredit Utang Gaji Rp2.000.000", "Debit Beban Gaji Rp2.000.000 – Kredit Utang Gaji Rp2.000.000", "Tidak perlu jurnal karena sebagian sudah dibayar"], answer: 1, solution: "1. Beban gaji periode ini penuh Rp6.000.000 → debit. 2. Kas berkurang Rp4.000.000 → kredit; Utang Gaji bertambah Rp2.000.000 → kredit. 3. Total kredit Rp6.000.000 = total debit. Kesalahan umum: hanya mencatat Rp2.000.000 yang terutang dan melupakan beban penuhnya." },
    { q: "Jika jurnal penyesuaian untuk pendapatan diterima di muka tidak dibuat, dampaknya adalah ...", options: ["Pendapatan terlalu tinggi dan liabilitas terlalu rendah", "Tidak ada dampak karena tidak ada kas yang bergerak", "Pendapatan terlalu rendah dan liabilitas terlalu tinggi", "Beban terlalu tinggi dan aset terlalu rendah"], answer: 2, solution: "1. Tanpa penyesuaian, pendapatan yang sudah dikerjakan belum diakui → pendapatan terlalu rendah. 2. Liabilitas (pendapatan diterima di muka) belum dikurangi → liabilitas terlalu tinggi. 3. Laba bersih pun ikut terlalu rendah. Kesalahan umum: mengira tidak ada dampak dengan alasan tidak ada kas yang bergerak." },
    { q: "Jika jurnal penyesuaian untuk beban yang masih harus dibayar (akrual) tidak dibuat, dampaknya adalah ...", options: ["Beban terlalu tinggi dan laba terlalu rendah", "Beban terlalu rendah, laba bersih terlalu tinggi, dan liabilitas terlalu rendah", "Aset terlalu rendah dan pendapatan terlalu tinggi", "Tidak ada dampak pada laporan keuangan"], answer: 1, solution: "1. Beban akrual yang belum dicatat → beban dilaporkan terlalu rendah. 2. Beban rendah → laba bersih terlalu tinggi; utang yang belum dicatat → liabilitas terlalu rendah. 3. Inilah alasan penyesuaian bersifat wajib, bukan opsional. Kesalahan umum: mengira penyesuaian hanya soal kerapian administrasi." },
    { q: "Dibayar sewa Rp12.000.000 untuk 12 bulan dan langsung dicatat sebagai Beban Sewa (pendekatan beban). Pada akhir periode, sewa yang sudah terpakai 2 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Sewa Rp10.000.000 – Kredit Sewa Dibayar di Muka Rp10.000.000", "Debit Sewa Dibayar di Muka Rp10.000.000 – Kredit Beban Sewa Rp10.000.000", "Debit Beban Sewa Rp2.000.000 – Kredit Kas Rp2.000.000", "Debit Sewa Dibayar di Muka Rp2.000.000 – Kredit Beban Sewa Rp2.000.000"], answer: 1, solution: "1. Sisa yang belum terpakai = 10 bulan × Rp1.000.000 = Rp10.000.000. 2. Karena awalnya dicatat sebagai beban, sisa ini harus diakui sebagai aset: Debit Sewa Dibayar di Muka Rp10.000.000, Kredit Beban Sewa Rp10.000.000. 3. Arah jurnalnya kebalikan dari pendekatan harta. Kesalahan umum: memakai jurnal pendekatan harta sehingga beban tercatat ganda." },
    { q: "Diterima Rp6.000.000 untuk 6 bulan jasa dan langsung dicatat sebagai Pendapatan Jasa (pendekatan pendapatan). Pada akhir periode, jasa yang sudah dikerjakan 2 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Pendapatan Diterima di Muka Rp4.000.000 – Kredit Pendapatan Jasa Rp4.000.000", "Debit Pendapatan Jasa Rp4.000.000 – Kredit Pendapatan Diterima di Muka Rp4.000.000", "Debit Kas Rp4.000.000 – Kredit Pendapatan Jasa Rp4.000.000", "Debit Pendapatan Jasa Rp2.000.000 – Kredit Pendapatan Diterima di Muka Rp2.000.000"], answer: 1, solution: "1. Yang belum dikerjakan = 4 bulan × Rp1.000.000 = Rp4.000.000. 2. Karena awalnya dicatat sebagai pendapatan, bagian yang belum dikerjakan harus menjadi liabilitas: Debit Pendapatan Jasa Rp4.000.000, Kredit Pendapatan Diterima di Muka Rp4.000.000. 3. Arah jurnalnya kebalikan dari pendekatan liabilitas. Kesalahan umum: menjurnal Rp2.000.000 yang sudah dikerjakan." },
    { q: "Dibayar iklan Rp4.800.000 untuk 8 bulan. Pada akhir periode, iklan yang sudah terpakai 3 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Iklan Rp1.800.000 – Kredit Iklan Dibayar di Muka Rp1.800.000", "Debit Beban Iklan Rp4.800.000 – Kredit Kas Rp4.800.000", "Debit Iklan Dibayar di Muka Rp3.000.000 – Kredit Beban Iklan Rp3.000.000", "Debit Beban Iklan Rp3.000.000 – Kredit Iklan Dibayar di Muka Rp3.000.000"], answer: 0, solution: "1. Iklan per bulan = Rp4.800.000 ÷ 8 = Rp600.000. 2. Terpakai 3 bulan → beban = 3 × Rp600.000 = Rp1.800.000. 3. Jurnal: Debit Beban Iklan Rp1.800.000, Kredit Iklan Dibayar di Muka Rp1.800.000. Kesalahan umum: menjurnal sisanya (Rp3.000.000) sebagai beban." },
    { q: "Saldo piutang usaha Rp50.000.000 dan perusahaan menaksir 2% tidak akan tertagih. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Kerugian Piutang Rp1.000.000 – Kredit Cadangan Kerugian Piutang Rp1.000.000", "Debit Cadangan Kerugian Piutang Rp1.000.000 – Kredit Piutang Usaha Rp1.000.000", "Debit Beban Kerugian Piutang Rp50.000.000 – Kredit Piutang Usaha Rp50.000.000", "Debit Piutang Usaha Rp1.000.000 – Kredit Beban Kerugian Piutang Rp1.000.000"], answer: 0, solution: "1. Taksiran tak tertagih = 2% × Rp50.000.000 = Rp1.000.000. 2. Jurnal: Debit Beban Kerugian Piutang Rp1.000.000, Kredit Cadangan Kerugian Piutang Rp1.000.000. 3. Cadangan adalah akun kontra aset piutang, bukan penghapusan langsung. Kesalahan umum: langsung mengkredit piutang usaha sebesar Rp1.000.000." },
    { q: "Pajak penghasilan terutang Rp2.500.000 belum dibayar sampai akhir periode. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Pajak Penghasilan Rp2.500.000 – Kredit Utang Pajak Penghasilan Rp2.500.000", "Debit Utang Pajak Penghasilan Rp2.500.000 – Kredit Kas Rp2.500.000", "Tidak dijurnal karena belum dibayar", "Debit Beban Pajak Penghasilan Rp2.500.000 – Kredit Kas Rp2.500.000"], answer: 0, solution: "1. Pajak periode ini sudah menjadi beban Rp2.500.000 → debit. 2. Belum dibayar → Utang Pajak Penghasilan Rp2.500.000 → kredit. 3. Basis akrual mencatat beban saat terutang. Kesalahan umum: mengkredit kas padahal kas belum keluar." },
    { q: "Dalam sistem periodik, persediaan awal barang dagang Rp18.000.000 dan persediaan akhir menurut opname Rp22.000.000. Jurnal penyesuaian untuk mencatat persediaan akhir adalah ...", options: ["Debit Persediaan Barang Dagang Rp22.000.000 – Kredit Ikhtisar Laba Rugi Rp22.000.000", "Debit Ikhtisar Laba Rugi Rp22.000.000 – Kredit Persediaan Barang Dagang Rp22.000.000", "Debit Persediaan Barang Dagang Rp18.000.000 – Kredit Ikhtisar Laba Rugi Rp18.000.000", "Debit HPP Rp22.000.000 – Kredit Persediaan Barang Dagang Rp22.000.000"], answer: 0, solution: "1. Persediaan akhir Rp22.000.000 harus muncul di neraca → Debit Persediaan Barang Dagang Rp22.000.000. 2. Pasangannya adalah Ikhtisar Laba Rugi → kredit. 3. Persediaan awal Rp18.000.000 dijurnal terbalik: Debit Ikhtisar Laba Rugi, Kredit Persediaan. Kesalahan umum: tertukar antara jurnal persediaan awal dan persediaan akhir." },
    { q: "Sewa Rp2.000.000 untuk bulan Desember sudah menjadi hak perusahaan tetapi penyewa belum membayar. Jurnal penyesuaiannya adalah ...", options: ["Debit Kas Rp2.000.000 – Kredit Pendapatan Sewa Rp2.000.000", "Debit Piutang Sewa Rp2.000.000 – Kredit Pendapatan Sewa Rp2.000.000", "Debit Pendapatan Sewa Rp2.000.000 – Kredit Piutang Sewa Rp2.000.000", "Tidak dijurnal sampai sewa diterima"], answer: 1, solution: "1. Sewa Desember sudah dihasilkan → Pendapatan Sewa Rp2.000.000 → kredit. 2. Belum diterima → Piutang Sewa Rp2.000.000 → debit. 3. Ini pendapatan akrual. Kesalahan umum: menunggu kas diterima baru mencatat." },
    { q: "Jika jurnal penyesuaian depresiasi tidak dibuat, dampaknya terhadap laporan keuangan adalah ...", options: ["Aset terlalu rendah dan beban terlalu tinggi", "Aset terlalu tinggi, beban terlalu rendah, dan laba bersih terlalu tinggi", "Liabilitas terlalu tinggi dan ekuitas terlalu rendah", "Tidak ada dampak karena depresiasi non-kas"], answer: 1, solution: "1. Tanpa penyesuaian, akumulasi depresiasi tidak bertambah → nilai buku aset terlalu tinggi. 2. Beban depresiasi tidak diakui → beban terlalu rendah dan laba bersih terlalu tinggi. 3. Alasan non-kas tidak menghapus kewajiban mencatat depresiasi. Kesalahan umum: mengira depresiasi boleh dilewatkan karena tidak ada kas yang keluar." },
    { q: "Perusahaan menerima sewa Rp12.000.000 untuk 12 bulan di muka (sebagai pemilik gedung). Pada akhir periode, sewa yang sudah berjalan 4 bulan. Jurnal penyesuaiannya adalah ...", options: ["Debit Sewa Diterima di Muka Rp12.000.000 – Kredit Pendapatan Sewa Rp12.000.000", "Debit Pendapatan Sewa Rp4.000.000 – Kredit Sewa Diterima di Muka Rp4.000.000", "Debit Sewa Diterima di Muka Rp4.000.000 – Kredit Pendapatan Sewa Rp4.000.000", "Debit Kas Rp4.000.000 – Kredit Pendapatan Sewa Rp4.000.000"], answer: 2, solution: "1. Sewa per bulan = Rp12.000.000 ÷ 12 = Rp1.000.000. 2. Sudah berjalan 4 bulan → pendapatan diakui = 4 × Rp1.000.000 = Rp4.000.000. 3. Jurnal: Debit Sewa Diterima di Muka Rp4.000.000, Kredit Pendapatan Sewa Rp4.000.000. Kesalahan umum: mengakui seluruh Rp12.000.000 sebagai pendapatan." },
    { q: "Gaji dibayar tiap Sabtu Rp4.200.000 untuk 6 hari kerja. Akhir periode jatuh pada hari Rabu (3 hari kerja telah lewat). Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Gaji Rp2.100.000 – Kredit Utang Gaji Rp2.100.000", "Debit Beban Gaji Rp4.200.000 – Kredit Utang Gaji Rp4.200.000", "Debit Beban Gaji Rp700.000 – Kredit Utang Gaji Rp700.000", "Tidak dijurnal karena gaji dibayar tiap Sabtu"], answer: 0, solution: "1. Gaji per hari = Rp4.200.000 ÷ 6 = Rp700.000. 2. Sudah lewat 3 hari → akrual = 3 × Rp700.000 = Rp2.100.000. 3. Jurnal: Debit Beban Gaji Rp2.100.000, Kredit Utang Gaji Rp2.100.000. Kesalahan umum: mencatat gaji seminggu penuh Rp4.200.000." },
    { q: "Dibeli perlengkapan Rp2.000.000 dan langsung dicatat sebagai Beban Perlengkapan (pendekatan beban). Hasil opname menunjukkan sisa Rp700.000. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Perlengkapan Rp700.000 – Kredit Perlengkapan Rp700.000", "Debit Perlengkapan Rp700.000 – Kredit Beban Perlengkapan Rp700.000", "Debit Perlengkapan Rp1.300.000 – Kredit Beban Perlengkapan Rp1.300.000", "Debit Beban Perlengkapan Rp1.300.000 – Kredit Perlengkapan Rp1.300.000"], answer: 1, solution: "1. Sisa Rp700.000 masih merupakan aset. 2. Karena awalnya dicatat sebagai beban, sisa ini harus dikembalikan menjadi aset: Debit Perlengkapan Rp700.000, Kredit Beban Perlengkapan Rp700.000. 3. Beban yang diakui = Rp2.000.000 − Rp700.000 = Rp1.300.000. Kesalahan umum: menjurnal Rp1.300.000 yang terpakai dengan arah yang salah." },
    { q: "Diterima di muka Rp10.000.000 untuk 10 bulan jasa. Pada akhir periode, tersisa 4 bulan jasa yang belum dikerjakan. Jurnal penyesuaiannya adalah ...", options: ["Debit Pendapatan Diterima di Muka Rp6.000.000 – Kredit Pendapatan Jasa Rp6.000.000", "Debit Pendapatan Diterima di Muka Rp4.000.000 – Kredit Pendapatan Jasa Rp4.000.000", "Debit Pendapatan Diterima di Muka Rp10.000.000 – Kredit Pendapatan Jasa Rp10.000.000", "Debit Pendapatan Jasa Rp6.000.000 – Kredit Pendapatan Diterima di Muka Rp6.000.000"], answer: 0, solution: "1. Jasa per bulan = Rp10.000.000 ÷ 10 = Rp1.000.000. 2. Sudah dikerjakan = 10 − 4 = 6 bulan → pendapatan diakui = 6 × Rp1.000.000 = Rp6.000.000. 3. Jurnal: Debit Pendapatan Diterima di Muka Rp6.000.000, Kredit Pendapatan Jasa Rp6.000.000. Kesalahan umum: menjurnal sisanya (Rp4.000.000) sebagai pendapatan." },
    { q: "Kendaraan dibeli Rp120.000.000 tanpa nilai sisa dan umur manfaat 5 tahun. Jurnal penyesuaian depresiasi tahun ini adalah ...", options: ["Debit Beban Depresiasi Rp24.000.000 – Kredit Akumulasi Depresiasi Rp24.000.000", "Debit Beban Depresiasi Rp24.000.000 – Kredit Kendaraan Rp24.000.000", "Debit Akumulasi Depresiasi Rp24.000.000 – Kredit Beban Depresiasi Rp24.000.000", "Debit Beban Depresiasi Rp120.000.000 – Kredit Akumulasi Depresiasi Rp120.000.000"], answer: 0, solution: "1. Depresiasi per tahun = Rp120.000.000 ÷ 5 = Rp24.000.000 (nilai sisa nol). 2. Jurnal: Debit Beban Depresiasi Rp24.000.000, Kredit Akumulasi Depresiasi Rp24.000.000. Kesalahan umum: mengkredit langsung akun Kendaraan." },
    { q: "Tujuan utama dibuatnya jurnal penyesuaian adalah ...", options: ["Agar total debit selalu sama dengan total kredit", "Agar pendapatan dan beban diakui pada periode yang tepat sesuai basis akrual", "Agar kas perusahaan bertambah", "Agar jumlah akun dalam buku besar berkurang"], answer: 1, solution: "1. Banyak transaksi (beban dibayar di muka, pendapatan diterima di muka, akrual, depresiasi) belum mencerminkan periode yang tepat. 2. Jurnal penyesuaian mengoreksinya agar laporan keuangan menyajikan pendapatan dan beban periode berjalan secara wajar. 3. Ini penerapan prinsip penandingan dan basis akrual. Kesalahan umum: mengira penyesuaian hanya formalitas agar neraca saldo seimbang." },
    { q: "Gedung dibeli Rp400.000.000 dengan nilai sisa Rp40.000.000 dan umur manfaat 20 tahun. Beban depresiasi per tahun metode garis lurus adalah ...", options: ["Rp20.000.000", "Rp18.000.000", "Rp2.000.000", "Rp360.000.000"], answer: 1, solution: "1. Rumus: (Harga perolehan − Nilai sisa) ÷ Umur manfaat. 2. (Rp400.000.000 − Rp40.000.000) ÷ 20 = Rp360.000.000 ÷ 20 = Rp18.000.000 per tahun. Kesalahan umum: tidak mengurangkan nilai sisa sehingga mendapat Rp20.000.000." },
    { q: "Peralatan dibeli Rp25.000.000 dengan nilai sisa Rp5.000.000 dan umur manfaat 4 tahun. Beban depresiasi per tahun adalah ...", options: ["Rp6.250.000", "Rp5.000.000", "Rp20.000.000", "Rp1.250.000"], answer: 1, solution: "1. (Rp25.000.000 − Rp5.000.000) ÷ 4 = Rp20.000.000 ÷ 4 = Rp5.000.000 per tahun. 2. Nilai sisa harus dikurangkan dulu sebelum dibagi umur manfaat. Kesalahan umum: membagi harga perolehan langsung dengan umur (Rp6.250.000)." },
    { q: "Kendaraan dibeli Rp180.000.000, nilai sisa Rp30.000.000, umur manfaat 5 tahun. Setelah dipakai 2 tahun, nilai bukunya adalah ...", options: ["Rp120.000.000", "Rp150.000.000", "Rp60.000.000", "Rp30.000.000"], answer: 0, solution: "1. Depresiasi per tahun = (Rp180.000.000 − Rp30.000.000) ÷ 5 = Rp30.000.000. 2. Akumulasi 2 tahun = 2 × Rp30.000.000 = Rp60.000.000. 3. Nilai buku = Rp180.000.000 − Rp60.000.000 = Rp120.000.000. Kesalahan umum: mengurangkan nilai sisa dua kali." },
    { q: "Mesin dibeli Rp96.000.000 dengan nilai sisa Rp12.000.000 dan umur manfaat 7 tahun. Beban depresiasi per tahun adalah ...", options: ["Rp12.000.000", "Rp13.714.286", "Rp84.000.000", "Rp6.000.000"], answer: 0, solution: "1. (Rp96.000.000 − Rp12.000.000) ÷ 7 = Rp84.000.000 ÷ 7 = Rp12.000.000 per tahun. 2. Nilai sisa wajib dikurangkan sebelum dibagi umur manfaat. Kesalahan umum: lupa mengurangkan nilai sisa." },
    { q: "Komputer dibeli Rp18.000.000, nilai sisa Rp3.000.000, umur manfaat 3 tahun. Setelah dipakai penuh 3 tahun, nilai bukunya adalah ...", options: ["Nol", "Rp3.000.000", "Rp18.000.000", "Rp15.000.000"], answer: 1, solution: "1. Depresiasi per tahun = (Rp18.000.000 − Rp3.000.000) ÷ 3 = Rp5.000.000. 2. Setelah 3 tahun, akumulasi = Rp15.000.000. 3. Nilai buku = Rp18.000.000 − Rp15.000.000 = Rp3.000.000, yaitu sebesar nilai sisanya. Kesalahan umum: mengira nilai buku menjadi nol padahal masih ada nilai sisa." },
    { q: "Aset tetap berikut yang TIDAK disusutkan adalah ...", options: ["Gedung", "Kendaraan", "Tanah", "Mesin"], answer: 2, solution: "1. Tanah memiliki umur manfaat tidak terbatas sehingga tidak disusutkan. 2. Gedung, kendaraan, dan mesin mengalami penurunan manfaat sehingga disusutkan. Kesalahan umum: menyusutkan tanah seperti aset tetap lainnya." },
    { q: "Peralatan dibeli Rp36.000.000, nilai sisa Rp6.000.000, umur manfaat 5 tahun. Beban depresiasi per bulan adalah ...", options: ["Rp500.000", "Rp600.000", "Rp6.000.000", "Rp2.500.000"], answer: 0, solution: "1. Depresiasi per tahun = (Rp36.000.000 − Rp6.000.000) ÷ 5 = Rp6.000.000. 2. Per bulan = Rp6.000.000 ÷ 12 = Rp500.000. Kesalahan umum: lupa membagi lagi dengan 12 bulan." },
    { q: "Gedung dibeli Rp300.000.000 tanpa nilai sisa, umur manfaat 25 tahun. Setelah dipakai 10 tahun, nilai bukunya adalah ...", options: ["Rp120.000.000", "Rp180.000.000", "Rp12.000.000", "Rp300.000.000"], answer: 1, solution: "1. Depresiasi per tahun = Rp300.000.000 ÷ 25 = Rp12.000.000. 2. Akumulasi 10 tahun = 10 × Rp12.000.000 = Rp120.000.000. 3. Nilai buku = Rp300.000.000 − Rp120.000.000 = Rp180.000.000. Kesalahan umum: mengira nilai buku sama dengan akumulasi depresiasinya (Rp120.000.000)." },
    { q: "Ciri beban depresiasi metode garis lurus adalah ...", options: ["Besarnya menurun setiap tahun", "Besarnya sama setiap tahun selama umur manfaat", "Besarnya naik setiap tahun", "Hanya diakui pada tahun pertama"], answer: 1, solution: "1. Garis lurus membagi nilai yang dapat disusutkan secara merata. 2. Maka beban depresiasi sama besar setiap tahun. 3. Metode yang bebannya menurun adalah metode saldo menurun. Kesalahan umum: mengacaukan garis lurus dengan metode saldo menurun." },
    { q: "Nilai sisa (salvage value) dalam perhitungan depresiasi adalah ...", options: ["Harga perolehan aset", "Taksiran nilai aset pada akhir umur manfaatnya", "Total beban depresiasi selama ini", "Harga pasar aset saat ini"], answer: 1, solution: "1. Nilai sisa adalah taksiran jumlah yang akan diperoleh dari pelepasan aset pada akhir umur manfaatnya. 2. Nilai inilah yang dikurangkan dari harga perolehan sebelum dibagi umur manfaat. Kesalahan umum: mengacaukannya dengan harga perolehan atau harga pasar saat ini." },
    { q: "Kendaraan dibeli Rp90.000.000, nilai sisa Rp18.000.000, umur manfaat 6 tahun, dan baru dipakai 6 bulan pada tahun pertama. Beban depresiasi tahun pertama adalah ...", options: ["Rp12.000.000", "Rp6.000.000", "Rp72.000.000", "Rp1.000.000"], answer: 1, solution: "1. Depresiasi per tahun = (Rp90.000.000 − Rp18.000.000) ÷ 6 = Rp12.000.000. 2. Baru dipakai 6 bulan → Rp12.000.000 × 6/12 = Rp6.000.000. Kesalahan umum: mencatat depresiasi setahun penuh walaupun aset baru dipakai 6 bulan." },
    { q: "Mesin dibeli Rp75.000.000, nilai sisa Rp15.000.000, umur manfaat 5 tahun. Setelah dipakai penuh 5 tahun, nilai bukunya adalah ...", options: ["Nol", "Rp60.000.000", "Rp15.000.000", "Rp75.000.000"], answer: 2, solution: "1. Depresiasi per tahun = (Rp75.000.000 − Rp15.000.000) ÷ 5 = Rp12.000.000. 2. Akumulasi 5 tahun = Rp60.000.000. 3. Nilai buku = Rp75.000.000 − Rp60.000.000 = Rp15.000.000 (nilai sisa). Kesalahan umum: mengira nilai buku habis menjadi nol." },
    { q: "Beban depresiasi bulanan Rp500.000. Jurnal penyesuaiannya adalah ...", options: ["Debit Beban Depresiasi Rp500.000 – Kredit Akumulasi Depresiasi Rp500.000", "Debit Akumulasi Depresiasi Rp500.000 – Kredit Beban Depresiasi Rp500.000", "Debit Beban Depresiasi Rp500.000 – Kredit Peralatan Rp500.000", "Debit Peralatan Rp500.000 – Kredit Kas Rp500.000"], answer: 0, solution: "1. Beban depresiasi diakui tiap bulan → Debit Beban Depresiasi Rp500.000. 2. Pasangannya adalah Akumulasi Depresiasi (kontra aset) → kredit Rp500.000. 3. Tidak ada kas yang keluar. Kesalahan umum: mengkredit kas atau langsung mengkredit akun asetnya." },
    { q: "Peralatan dibeli Rp50.000.000 dengan depresiasi Rp8.000.000 per tahun. Setelah dipakai 4 tahun, nilai bukunya adalah ...", options: ["Rp32.000.000", "Rp18.000.000", "Rp8.000.000", "Rp42.000.000"], answer: 1, solution: "1. Akumulasi depresiasi = 4 × Rp8.000.000 = Rp32.000.000. 2. Nilai buku = Rp50.000.000 − Rp32.000.000 = Rp18.000.000. Kesalahan umum: mengurangkan depresiasi 1 tahun saja (mendapat Rp42.000.000)." },
    { q: "Peralatan dibeli Rp48.000.000, nilai sisa Rp8.000.000, umur manfaat 8 tahun. Setelah dipakai 3 tahun, nilai bukunya adalah ...", options: ["Rp33.000.000", "Rp15.000.000", "Rp5.000.000", "Rp43.000.000"], answer: 0, solution: "1. Depresiasi per tahun = (Rp48.000.000 − Rp8.000.000) ÷ 8 = Rp5.000.000. 2. Akumulasi 3 tahun = Rp15.000.000. 3. Nilai buku = Rp48.000.000 − Rp15.000.000 = Rp33.000.000. Kesalahan umum: lupa mengalikan depresiasi tahunan dengan lama pemakaian." },
    { q: "Berikut ini faktor yang menentukan besarnya depresiasi garis lurus, KECUALI ...", options: ["Harga perolehan", "Nilai sisa", "Umur manfaat", "Harga pasar aset saat ini"], answer: 3, solution: "1. Depresiasi garis lurus hanya memakai harga perolehan, nilai sisa, dan umur manfaat. 2. Harga pasar saat ini tidak dipakai karena akuntansi memakai biaya historis, bukan nilai wajar fluktuatif. Kesalahan umum: memakai harga pasar terkini dalam perhitungan depresiasi." },
    { q: "Pendapatan jasa Rp150.000.000 dan total beban Rp95.000.000. Laba bersih perusahaan adalah ...", options: ["Rp55.000.000", "Rp245.000.000", "Rp95.000.000", "Rp150.000.000"], answer: 0, solution: "1. Laba bersih = Pendapatan − Beban. 2. Rp150.000.000 − Rp95.000.000 = Rp55.000.000. Kesalahan umum: menjumlahkan pendapatan dan beban menjadi Rp245.000.000." },
    { q: "Penjualan Rp200.000.000, harga pokok penjualan Rp120.000.000, dan beban operasional Rp50.000.000. Laba bersih perusahaan adalah ...", options: ["Rp80.000.000", "Rp30.000.000", "Rp130.000.000", "Rp200.000.000"], answer: 1, solution: "1. Laba kotor = Rp200.000.000 − Rp120.000.000 = Rp80.000.000. 2. Laba bersih = Rp80.000.000 − Rp50.000.000 = Rp30.000.000. Kesalahan umum: berhenti di laba kotor Rp80.000.000 dan lupa mengurangkan beban operasional." },
    { q: "Penjualan Rp200.000.000 dan harga pokok penjualan Rp120.000.000. Laba kotor perusahaan adalah ...", options: ["Rp320.000.000", "Rp80.000.000", "Rp120.000.000", "Rp30.000.000"], answer: 1, solution: "1. Laba kotor = Penjualan − Harga Pokok Penjualan. 2. Rp200.000.000 − Rp120.000.000 = Rp80.000.000. Kesalahan umum: mengurangkan beban operasional juga sehingga mendapat laba bersih Rp30.000.000." },
    { q: "Total pendapatan Rp60.000.000 sedangkan total beban Rp72.000.000. Kondisi perusahaan adalah ...", options: ["Laba bersih Rp12.000.000", "Impas", "Rugi bersih Rp12.000.000", "Laba bersih Rp132.000.000"], answer: 2, solution: "1. Selisih = Rp60.000.000 − Rp72.000.000 = −Rp12.000.000. 2. Hasil negatif berarti rugi bersih Rp12.000.000. Kesalahan umum: tetap menyebutnya laba bersih Rp12.000.000." },
    { q: "Laba kotor Rp45.000.000, beban penjualan Rp10.000.000, dan beban administrasi Rp15.000.000. Laba usaha perusahaan adalah ...", options: ["Rp70.000.000", "Rp20.000.000", "Rp35.000.000", "Rp30.000.000"], answer: 1, solution: "1. Laba usaha = Laba kotor − Beban penjualan − Beban administrasi. 2. Rp45.000.000 − Rp10.000.000 − Rp15.000.000 = Rp20.000.000. Kesalahan umum: hanya mengurangkan salah satu beban." },
    { q: "Laba usaha Rp20.000.000 dan pendapatan bunga Rp2.000.000. Laba sebelum pajak perusahaan adalah ...", options: ["Rp18.000.000", "Rp22.000.000", "Rp20.000.000", "Rp24.000.000"], answer: 1, solution: "1. Laba sebelum pajak = Laba usaha + Pendapatan lain-lain. 2. Rp20.000.000 + Rp2.000.000 = Rp22.000.000. Kesalahan umum: mengurangkan pendapatan bunga menjadi Rp18.000.000." },
    { q: "Laba sebelum pajak Rp22.000.000 dan tarif pajak penghasilan 10%. Laba bersih setelah pajak adalah ...", options: ["Rp19.800.000", "Rp22.000.000", "Rp2.200.000", "Rp24.200.000"], answer: 0, solution: "1. Pajak = 10% × Rp22.000.000 = Rp2.200.000. 2. Laba bersih = Rp22.000.000 − Rp2.200.000 = Rp19.800.000. Kesalahan umum: mengira laba bersih sama dengan laba sebelum pajak." },
    { q: "Perusahaan jasa memperoleh pendapatan Rp95.000.000 dengan beban gaji Rp40.000.000, beban sewa Rp12.000.000, dan beban lain-lain Rp8.000.000. Laba bersihnya adalah ...", options: ["Rp35.000.000", "Rp155.000.000", "Rp55.000.000", "Rp43.000.000"], answer: 0, solution: "1. Total beban = Rp40.000.000 + Rp12.000.000 + Rp8.000.000 = Rp60.000.000. 2. Laba bersih = Rp95.000.000 − Rp60.000.000 = Rp35.000.000. Kesalahan umum: lupa menjumlahkan semua beban terlebih dahulu." },
    { q: "Penjualan Rp100.000.000 menghasilkan laba kotor Rp40.000.000. Margin laba kotor perusahaan adalah ...", options: ["2,5%", "40%", "60%", "250%"], answer: 1, solution: "1. Margin laba kotor = Laba kotor ÷ Penjualan × 100%. 2. Rp40.000.000 ÷ Rp100.000.000 × 100% = 40%. Kesalahan umum: membalik pembilang dan penyebut sehingga mendapat 250%." },
    { q: "Jika total beban naik sedangkan total pendapatan tetap, maka laba bersih akan ...", options: ["Naik", "Tetap", "Turun", "Menjadi nol"], answer: 2, solution: "1. Laba bersih = Pendapatan − Beban. 2. Beban yang naik menggerus selisih sehingga laba bersih turun (bahkan bisa menjadi rugi). Kesalahan umum: mengira laba ikut naik karena beban yang besar menandakan usaha yang besar." },
    { q: "Akun-akun berikut dilaporkan dalam laporan laba rugi, KECUALI ...", options: ["Pendapatan Jasa", "Beban Gaji", "Kas", "Beban Sewa"], answer: 2, solution: "1. Laporan laba rugi memuat akun nominal: pendapatan dan beban. 2. Kas adalah akun riil (aset) yang dilaporkan di neraca, bukan di laporan laba rugi. Kesalahan umum: memasukkan kas ke laporan laba rugi dengan alasan kas berkaitan dengan pendapatan." },
    { q: "Penjualan kotor Rp50.000.000 dengan retur penjualan Rp3.000.000. Penjualan bersih perusahaan adalah ...", options: ["Rp53.000.000", "Rp47.000.000", "Rp50.000.000", "Rp3.000.000"], answer: 1, solution: "1. Penjualan bersih = Penjualan kotor − Retur penjualan. 2. Rp50.000.000 − Rp3.000.000 = Rp47.000.000. Kesalahan umum: menjumlahkan retur ke penjualan menjadi Rp53.000.000." },
    { q: "Penjualan Rp50.000.000, retur penjualan Rp3.000.000, dan potongan penjualan Rp1.000.000. Penjualan bersihnya adalah ...", options: ["Rp46.000.000", "Rp54.000.000", "Rp47.000.000", "Rp48.000.000"], answer: 0, solution: "1. Penjualan bersih = Rp50.000.000 − Rp3.000.000 − Rp1.000.000 = Rp46.000.000. 2. Retur dan potongan penjualan sama-sama mengurangi penjualan kotor. Kesalahan umum: lupa mengurangkan salah satunya." },
    { q: "Persediaan awal Rp20.000.000, pembelian bersih Rp80.000.000, dan persediaan akhir Rp25.000.000. Harga pokok penjualan adalah ...", options: ["Rp75.000.000", "Rp125.000.000", "Rp85.000.000", "Rp55.000.000"], answer: 0, solution: "1. HPP = Persediaan awal + Pembelian bersih − Persediaan akhir. 2. Rp20.000.000 + Rp80.000.000 − Rp25.000.000 = Rp75.000.000. Kesalahan umum: menjumlahkan persediaan akhir menjadi Rp125.000.000." },
    { q: "Modal awal Rp150.000.000, laba bersih Rp25.000.000, dan prive Rp10.000.000. Modal akhir periode adalah ...", options: ["Rp165.000.000", "Rp185.000.000", "Rp135.000.000", "Rp175.000.000"], answer: 0, solution: "1. Modal akhir = Modal awal + Laba bersih − Prive. 2. Rp150.000.000 + Rp25.000.000 − Rp10.000.000 = Rp165.000.000. Kesalahan umum: menambah prive menjadi Rp185.000.000." },
    { q: "Modal awal Rp90.000.000, rugi bersih Rp12.000.000, prive Rp3.000.000, dan setoran tambahan Rp20.000.000. Modal akhir periode adalah ...", options: ["Rp101.000.000", "Rp95.000.000", "Rp115.000.000", "Rp75.000.000"], answer: 1, solution: "1. Modal akhir = Rp90.000.000 − Rp12.000.000 − Rp3.000.000 + Rp20.000.000 = Rp95.000.000. 2. Rugi dan prive mengurangi modal, setoran menambah modal. Kesalahan umum: lupa memasukkan setoran tambahan." },
    { q: "Modal awal Rp200.000.000, laba bersih Rp40.000.000, prive Rp10.000.000, dan modal akhir Rp250.000.000. Setoran tambahan modal sebesar ...", options: ["Rp20.000.000", "Rp40.000.000", "Rp10.000.000", "Nol"], answer: 0, solution: "1. Rp200.000.000 + Rp40.000.000 − Rp10.000.000 + Setoran = Rp250.000.000. 2. Rp230.000.000 + Setoran = Rp250.000.000 → Setoran = Rp20.000.000. Kesalahan umum: mengabaikan prive dalam perhitungan." },
    { q: "Modal awal Rp75.000.000, rugi bersih Rp20.000.000, dan prive Rp5.000.000. Modal akhir periode adalah ...", options: ["Rp100.000.000", "Rp60.000.000", "Rp50.000.000", "Rp90.000.000"], answer: 2, solution: "1. Modal akhir = Rp75.000.000 − Rp20.000.000 − Rp5.000.000 = Rp50.000.000. 2. Rugi bersih dan prive sama-sama mengurangi modal. Kesalahan umum: hanya mengurangkan salah satunya." },
    { q: "Laporan perubahan modal menyajikan ...", options: ["Arus kas masuk dan keluar perusahaan", "Perubahan ekuitas pemilik selama satu periode akuntansi", "Total aset dan liabilitas perusahaan", "Rincian seluruh transaksi harian"], answer: 1, solution: "1. Laporan perubahan modal merangkum perubahan ekuitas: modal awal, laba/rugi bersih, prive, dan setoran tambahan. 2. Hasilnya adalah modal akhir yang akan dilaporkan di neraca. Kesalahan umum: mengacaukannya dengan laporan arus kas." },
    { q: "Modal awal Rp120.000.000, laba bersih Rp18.000.000, dan prive Rp7.000.000. Modal akhir periode adalah ...", options: ["Rp131.000.000", "Rp145.000.000", "Rp109.000.000", "Rp138.000.000"], answer: 0, solution: "1. Modal akhir = Rp120.000.000 + Rp18.000.000 − Rp7.000.000 = Rp131.000.000. 2. Laba menambah modal, prive mengurangi modal. Kesalahan umum: menambah prive menjadi Rp145.000.000." },
    { q: "Setoran tambahan modal Rp15.000.000 oleh pemilik dicatat dalam laporan perubahan modal sebagai ...", options: ["Pengurang modal", "Penambah modal", "Beban periode berjalan", "Liabilitas perusahaan"], answer: 1, solution: "1. Setoran tambahan menambah investasi pemilik di perusahaan. 2. Maka ia menambah modal dalam laporan perubahan modal. Kesalahan umum: mencatatnya sebagai pendapatan atau liabilitas." },
    { q: "Modal awal Rp160.000.000, modal akhir Rp180.000.000, dan prive Rp8.000.000 tanpa setoran tambahan. Laba bersih periode ini sebesar ...", options: ["Rp12.000.000", "Rp28.000.000", "Rp20.000.000", "Rp36.000.000"], answer: 1, solution: "1. Rp160.000.000 + Laba − Rp8.000.000 = Rp180.000.000. 2. Laba = Rp180.000.000 − Rp160.000.000 + Rp8.000.000 = Rp28.000.000. Kesalahan umum: lupa menambahkan kembali prive yang telah mengurangi modal." },
    { q: "Urutan penyusunan laporan keuangan yang benar adalah ...", options: ["Neraca, laba rugi, perubahan modal, arus kas", "Laba rugi, perubahan modal, neraca, arus kas", "Arus kas, neraca, laba rugi, perubahan modal", "Perubahan modal, arus kas, neraca, laba rugi"], answer: 1, solution: "1. Laba rugi disusun dulu untuk menghasilkan laba/rugi bersih. 2. Laba/rugi dipakai dalam laporan perubahan modal untuk menghasilkan modal akhir. 3. Modal akhir dilaporkan di neraca; arus kas disusun terakhir. Kesalahan umum: menyusun neraca sebelum laba rugi." },
    { q: "Modal awal Rp100.000.000, perusahaan mengalami rugi bersih Rp10.000.000, tanpa prive dan setoran tambahan. Modal akhir periode adalah ...", options: ["Rp110.000.000", "Rp90.000.000", "Rp100.000.000", "Rp10.000.000"], answer: 1, solution: "1. Modal akhir = Rp100.000.000 − Rp10.000.000 = Rp90.000.000. 2. Rugi bersih mengurangi modal. Kesalahan umum: menambah rugi ke modal menjadi Rp110.000.000." },
    { q: "Berikut ini kelompok aset tetap, KECUALI ...", options: ["Tanah", "Gedung", "Kendaraan", "Piutang Usaha"], answer: 3, solution: "1. Tanah, gedung, dan kendaraan dipakai lebih dari satu periode sehingga termasuk aset tetap. 2. Piutang usaha diharapkan menjadi kas dalam waktu dekat sehingga termasuk aset lancar. Kesalahan umum: menggolongkan piutang sebagai aset tetap karena nilainya besar." },
    { q: "Utang usaha diklasifikasikan sebagai ...", options: ["Aset lancar", "Liabilitas jangka pendek", "Liabilitas jangka panjang", "Ekuitas"], answer: 1, solution: "1. Utang usaha umumnya jatuh tempo dalam waktu kurang dari satu tahun. 2. Kewajiban yang jatuh tempo dalam satu tahun termasuk liabilitas jangka pendek. Kesalahan umum: menggolongkannya sebagai liabilitas jangka panjang." },
    { q: "Utang bank yang jatuh tempo lebih dari satu tahun diklasifikasikan sebagai ...", options: ["Liabilitas jangka pendek", "Aset tetap", "Liabilitas jangka panjang", "Ekuitas"], answer: 2, solution: "1. Batasnya adalah satu tahun (atau satu siklus operasi). 2. Utang yang jatuh tempo lebih dari satu tahun termasuk liabilitas jangka panjang. Kesalahan umum: menggolongkan semua utang bank sebagai jangka pendek." },
    { q: "Modal pemilik dalam neraca diklasifikasikan sebagai ...", options: ["Aset", "Liabilitas", "Ekuitas", "Pendapatan"], answer: 2, solution: "1. Modal adalah hak pemilik atas aset perusahaan. 2. Hak pemilik dilaporkan sebagai ekuitas, bukan liabilitas. Kesalahan umum: mengira modal adalah utang perusahaan kepada pemilik." },
    { q: "Piutang usaha dalam neraca diklasifikasikan sebagai ...", options: ["Aset lancar", "Aset tetap", "Liabilitas jangka pendek", "Ekuitas"], answer: 0, solution: "1. Piutang usaha diharapkan tertagih menjadi kas dalam waktu kurang dari satu tahun. 2. Maka ia termasuk aset lancar. Kesalahan umum: menggolongkannya sebagai aset tetap." },
    { q: "Gedung dalam neraca diklasifikasikan sebagai ...", options: ["Aset lancar", "Aset tetap", "Liabilitas jangka panjang", "Ekuitas"], answer: 1, solution: "1. Gedung dipakai dalam operasi lebih dari satu tahun. 2. Maka ia termasuk aset tetap (aset tidak lancar). Kesalahan umum: mengira semua aset berwujud otomatis aset lancar." },
    { q: "Sewa dibayar di muka dalam neraca diklasifikasikan sebagai ...", options: ["Beban", "Aset lancar", "Liabilitas jangka pendek", "Ekuitas"], answer: 1, solution: "1. Sewa dibayar di muka adalah hak memakai yang akan dinikmati dalam waktu dekat. 2. Maka ia termasuk aset lancar. Kesalahan umum: langsung menggolongkannya sebagai beban." },
    { q: "Utang gaji dalam neraca diklasifikasikan sebagai ...", options: ["Beban", "Liabilitas jangka pendek", "Liabilitas jangka panjang", "Aset lancar"], answer: 1, solution: "1. Utang gaji umumnya dibayar dalam waktu dekat (kurang dari satu tahun). 2. Maka ia termasuk liabilitas jangka pendek. Kesalahan umum: menggolongkannya sebagai beban di neraca." },
    { q: "Pendapatan diterima di muka dalam neraca diklasifikasikan sebagai ...", options: ["Pendapatan", "Aset lancar", "Liabilitas jangka pendek", "Ekuitas"], answer: 2, solution: "1. Pendapatan diterima di muka adalah kewajiban mengerjakan jasa di masa depan. 2. Kewajiban jangka pendek ini dilaporkan sebagai liabilitas jangka pendek. Kesalahan umum: menggolongkannya sebagai pendapatan dalam neraca." },
    { q: "Akumulasi depresiasi dalam neraca disajikan sebagai ...", options: ["Penambah aset tetap", "Liabilitas jangka panjang", "Pengurang aset tetap", "Beban operasional"], answer: 2, solution: "1. Akumulasi depresiasi adalah akun kontra aset. 2. Ia disajikan sebagai pengurang kelompok aset tetap untuk menghasilkan nilai buku. Kesalahan umum: menyajikannya sebagai liabilitas." },
    { q: "Perlengkapan dalam neraca diklasifikasikan sebagai ...", options: ["Aset tetap", "Aset lancar", "Beban", "Liabilitas jangka pendek"], answer: 1, solution: "1. Perlengkapan akan terpakai dalam kegiatan operasi kurang dari satu tahun. 2. Maka ia termasuk aset lancar. Kesalahan umum: menggolongkannya sebagai aset tetap karena berwujud." },
    { q: "Investasi jangka panjang (misalnya saham perusahaan lain untuk 5 tahun) diklasifikasikan sebagai ...", options: ["Aset lancar", "Aset tidak lancar", "Liabilitas jangka panjang", "Ekuitas"], answer: 1, solution: "1. Investasi yang dipegang lebih dari satu tahun bukan aset lancar. 2. Ia dilaporkan sebagai aset tidak lancar (investasi jangka panjang). Kesalahan umum: menggolongkannya sebagai aset lancar karena berupa surat berharga." },
    { q: "Utang pajak dalam neraca diklasifikasikan sebagai ...", options: ["Aset lancar", "Ekuitas", "Liabilitas jangka pendek", "Liabilitas jangka panjang"], answer: 2, solution: "1. Utang pajak umumnya harus dibayar dalam waktu kurang dari satu tahun. 2. Maka ia termasuk liabilitas jangka pendek. Kesalahan umum: menggolongkannya sebagai beban dalam neraca." },
    { q: "Total aset Rp300.000.000, liabilitas jangka pendek Rp60.000.000, dan liabilitas jangka panjang Rp90.000.000. Total ekuitas yang dilaporkan sebesar ...", options: ["Rp450.000.000", "Rp150.000.000", "Rp210.000.000", "Rp300.000.000"], answer: 1, solution: "1. Total liabilitas = Rp60.000.000 + Rp90.000.000 = Rp150.000.000. 2. Ekuitas = Rp300.000.000 − Rp150.000.000 = Rp150.000.000. 3. Neraca harus seimbang. Kesalahan umum: hanya mengurangkan liabilitas jangka pendek." },
    { q: "Aset lancar Rp80.000.000 dan aset tetap (neto) Rp120.000.000. Total aset yang dilaporkan di neraca sebesar ...", options: ["Rp40.000.000", "Rp200.000.000", "Rp80.000.000", "Rp120.000.000"], answer: 1, solution: "1. Total aset = Aset lancar + Aset tidak lancar. 2. Rp80.000.000 + Rp120.000.000 = Rp200.000.000. Kesalahan umum: mengurangkan keduanya menjadi Rp40.000.000." },
    { q: "Kas Rp25.000.000, piutang usaha Rp35.000.000, dan perlengkapan Rp5.000.000. Total aset lancar sebesar ...", options: ["Rp65.000.000", "Rp60.000.000", "Rp30.000.000", "Rp55.000.000"], answer: 0, solution: "1. Total aset lancar = Rp25.000.000 + Rp35.000.000 + Rp5.000.000 = Rp65.000.000. 2. Ketiganya adalah aset lancar. Kesalahan umum: lupa memasukkan perlengkapan." },
    { q: "Urutan penyajian aset lancar dalam neraca berdasarkan tingkat likuiditas adalah ...", options: ["Perlengkapan, piutang usaha, kas", "Kas, piutang usaha, perlengkapan", "Piutang usaha, kas, perlengkapan", "Kas, perlengkapan, piutang usaha"], answer: 1, solution: "1. Aset lancar disusun dari yang paling likuid (cepat menjadi kas). 2. Urutannya: kas, piutang usaha, perlengkapan, lalu sewa dibayar di muka. Kesalahan umum: menyusun berdasarkan abjad atau besarnya nilai." },
    { q: "Wesel bayar yang jatuh tempo 3 tahun lagi diklasifikasikan sebagai ...", options: ["Liabilitas jangka pendek", "Aset lancar", "Liabilitas jangka panjang", "Ekuitas"], answer: 2, solution: "1. Jatuh tempo 3 tahun berarti lebih dari satu tahun. 2. Maka wesel bayar ini termasuk liabilitas jangka panjang. Kesalahan umum: menggolongkan semua wesel bayar sebagai jangka pendek." },
    { q: "Penerimaan pelunasan piutang Rp25.000.000 diklasifikasikan dalam laporan arus kas sebagai aktivitas ...", options: ["Investasi", "Operasi", "Pendanaan", "Non-kas"], answer: 1, solution: "1. Piutang berasal dari penjualan/pendapatan usaha sehari-hari. 2. Maka pelunasannya termasuk aktivitas operasi. Kesalahan umum: menggolongkannya sebagai aktivitas investasi karena menerima kas dalam jumlah besar." },
    { q: "Pembayaran prive Rp10.000.000 diklasifikasikan dalam laporan arus kas sebagai aktivitas ...", options: ["Operasi", "Investasi", "Pendanaan", "Non-kas"], answer: 2, solution: "1. Prive adalah distribusi kepada pemilik. 2. Transaksi dengan pemilik termasuk aktivitas pendanaan. Kesalahan umum: menggolongkannya sebagai aktivitas operasi." },
    { q: "Penerimaan pinjaman bank Rp80.000.000 diklasifikasikan dalam laporan arus kas sebagai aktivitas ...", options: ["Operasi", "Pendanaan", "Investasi", "Non-kas"], answer: 1, solution: "1. Pinjaman bank adalah transaksi pendanaan (memperoleh dana). 2. Maka ia termasuk aktivitas pendanaan (arus masuk). Kesalahan umum: menggolongkannya sebagai aktivitas operasi karena kasnya dipakai untuk operasional." },
    { q: "Pembayaran angsuran utang bank Rp30.000.000 diklasifikasikan sebagai aktivitas ...", options: ["Operasi", "Investasi", "Pendanaan", "Non-kas"], answer: 2, solution: "1. Pembayaran kembali pinjaman adalah transaksi pendanaan. 2. Ia dilaporkan sebagai arus kas keluar dari aktivitas pendanaan. Kesalahan umum: menggolongkannya sebagai aktivitas operasi." },
    { q: "Penjualan peralatan lama Rp12.000.000 secara tunai diklasifikasikan sebagai aktivitas ...", options: ["Operasi", "Pendanaan", "Investasi", "Non-kas"], answer: 2, solution: "1. Peralatan adalah aset tetap jangka panjang. 2. Penjualan aset tetap termasuk aktivitas investasi. Kesalahan umum: menggolongkannya sebagai aktivitas operasi karena menghasilkan kas." },
    { q: "Kas diterima dari pelanggan Rp100.000.000, kas dibayar ke pemasok Rp55.000.000, dan kas dibayar untuk gaji Rp20.000.000. Arus kas bersih dari aktivitas operasi sebesar ...", options: ["Rp175.000.000", "Rp25.000.000", "Rp45.000.000", "Rp35.000.000"], answer: 1, solution: "1. Arus kas operasi = Rp100.000.000 − Rp55.000.000 − Rp20.000.000 = Rp25.000.000. 2. Ketiganya adalah transaksi operasional sehari-hari. Kesalahan umum: menjumlahkan semuanya menjadi Rp175.000.000." },
    { q: "Pembelian tanah Rp150.000.000 secara tunai diklasifikasikan sebagai aktivitas ...", options: ["Operasi", "Pendanaan", "Investasi", "Non-kas"], answer: 2, solution: "1. Tanah adalah aset jangka panjang. 2. Pembelian aset jangka panjang termasuk aktivitas investasi (arus keluar). Kesalahan umum: menggolongkannya sebagai aktivitas operasi hanya karena mengeluarkan kas." },
    { q: "Setoran modal pemilik Rp40.000.000 secara tunai diklasifikasikan sebagai aktivitas ...", options: ["Operasi", "Investasi", "Pendanaan", "Non-kas"], answer: 2, solution: "1. Setoran modal adalah transaksi dengan pemilik. 2. Transaksi ekuitas/utang termasuk aktivitas pendanaan (arus masuk). Kesalahan umum: menggolongkannya sebagai aktivitas operasi." },
    { q: "Pembayaran beban sewa Rp6.000.000 secara tunai diklasifikasikan sebagai aktivitas ...", options: ["Pendanaan", "Investasi", "Operasi", "Non-kas"], answer: 2, solution: "1. Sewa adalah beban operasional sehari-hari. 2. Pembayarannya termasuk arus kas keluar dari aktivitas operasi. Kesalahan umum: menggolongkannya sebagai aktivitas investasi." },
    { q: "Arus kas dari operasi +Rp25.000.000, dari investasi −Rp40.000.000, dan dari pendanaan +Rp30.000.000. Kenaikan kas bersih sebesar ...", options: ["Rp95.000.000", "Rp15.000.000", "Rp−15.000.000", "Rp55.000.000"], answer: 1, solution: "1. Kenaikan kas bersih = Rp25.000.000 − Rp40.000.000 + Rp30.000.000 = Rp15.000.000. 2. Tanda negatif pada investasi berarti arus keluar. Kesalahan umum: menjumlahkan nilai mutlaknya menjadi Rp95.000.000." },
    { q: "Metode langsung dan metode tidak langsung dalam laporan arus kas digunakan untuk menyajikan ...", options: ["Aktivitas investasi", "Aktivitas pendanaan", "Aktivitas operasi", "Seluruh aktivitas"], answer: 2, solution: "1. Perbedaan metode langsung dan tidak langsung hanya pada penyajian arus kas dari aktivitas operasi. 2. Aktivitas investasi dan pendanaan disajikan sama pada kedua metode. Kesalahan umum: mengira kedua metode berlaku untuk seluruh laporan." },
    { q: "Penerimaan bunga bank Rp1.000.000 diklasifikasikan sebagai aktivitas ...", options: ["Investasi", "Pendanaan", "Non-kas", "Operasi"], answer: 3, solution: "1. Bunga yang diterima berkaitan dengan hasil operasional/pendapatan. 2. Dalam praktik umum ia dilaporkan sebagai arus kas masuk aktivitas operasi. Kesalahan umum: menggolongkannya sebagai aktivitas investasi karena berasal dari bank." },
    { q: "Prinsip yang menganggap perusahaan akan terus beroperasi di masa depan disebut ...", options: ["Konservatisme", "Going concern (kelangsungan usaha)", "Biaya historis", "Materialitas"], answer: 1, solution: "1. Going concern adalah asumsi bahwa perusahaan akan melanjutkan operasinya dan tidak akan dilikuidasi dalam waktu dekat. 2. Asumsi ini mendasari penyusutan aset tetap dan klasifikasi lancar/tidak lancar. Kesalahan umum: mengacaukannya dengan konservatisme." },
    { q: "Prinsip konservatisme dalam akuntansi berarti ...", options: ["Selalu melaporkan laba sebesar-besarnya", "Bersikap hati-hati: mengakui kerugian lebih cepat dan menunda pengakuan keuntungan yang belum pasti", "Menggunakan metode yang berbeda setiap periode", "Mencatat semua transaksi sebesar nilai pasarnya"], answer: 1, solution: "1. Konservatisme menuntut kehati-hatian agar aset dan laba tidak dilaporkan berlebihan. 2. Kerugian yang mungkin terjadi diakui lebih dini, sedangkan keuntungan menunggu sampai benar-benar terealisasi. Kesalahan umum: mengira konservatisme berarti melaporkan laba sebesar-besarnya." },
    { q: "Berdasarkan prinsip biaya historis, aset tetap dicatat sebesar ...", options: ["Nilai pasar saat ini", "Harga perolehan saat dibeli", "Taksiran harga jual kembali", "Nilai bukunya setiap tahun"], answer: 1, solution: "1. Prinsip biaya historis mencatat aset sebesar biaya yang dikeluarkan untuk memperolehnya. 2. Nilai ini objektif dan dapat diverifikasi dari bukti transaksi. Kesalahan umum: mencatat aset sebesar nilai pasar terkini yang fluktuatif." },
    { q: "Prinsip entitas ekonomi mengharuskan ...", options: ["Menggabungkan keuangan perusahaan dan pemilik", "Memisahkan transaksi perusahaan dari transaksi pribadi pemilik", "Mencatat semua transaksi dalam mata uang asing", "Menyamakan metode akuntansi semua perusahaan"], answer: 1, solution: "1. Perusahaan dianggap sebagai entitas yang terpisah dari pemiliknya. 2. Transaksi pribadi pemilik tidak boleh dicampur dengan transaksi perusahaan. Kesalahan umum: mencatat pengeluaran pribadi pemilik sebagai beban perusahaan." },
    { q: "Prinsip periode akuntansi menyatakan bahwa ...", options: ["Perusahaan hanya boleh berdiri selama satu tahun", "Umur perusahaan dibagi menjadi periode-periode waktu (tahunan, kuartalan, bulanan) untuk pelaporan", "Laporan keuangan hanya dibuat saat perusahaan tutup", "Semua transaksi dicatat pada akhir tahun"], answer: 1, solution: "1. Umur perusahaan yang panjang dibagi menjadi periode agar kinerjanya dapat dinilai berkala. 2. Inilah dasar penyusunan laporan keuangan tahunan dan jurnal penyesuaian. Kesalahan umum: mengira perusahaan harus dilikuidasi setiap akhir periode." },
    { q: "Prinsip konsistensi mengharuskan perusahaan ...", options: ["Menggunakan metode akuntansi yang sama dari periode ke periode", "Mencatat semua transaksi dengan jumlah yang sama", "Tidak boleh mengganti metode akuntansi selamanya", "Menyamakan laporannya dengan perusahaan lain"], answer: 0, solution: "1. Konsistensi berarti metode yang dipilih dipakai terus agar laporan antarperiode dapat dibandingkan. 2. Perubahan metode masih boleh, asalkan diungkapkan alasannya. Kesalahan umum: mengira metode akuntansi tidak boleh diubah sama sekali." },
    { q: "Prinsip materialitas berarti ...", options: ["Semua transaksi sekecil apa pun harus dirinci", "Hanya informasi yang cukup penting untuk memengaruhi keputusan yang perlu diungkapkan rinci", "Laporan keuangan harus dicetak di kertas tebal", "Aset harus selalu dinilai material"], answer: 1, solution: "1. Informasi dianggap material jika penghilangannya dapat mengubah keputusan pengguna laporan. 2. Hal yang tidak material boleh disederhanakan agar laporan tidak bertele-tele. Kesalahan umum: merinci setiap transaksi kecil sehingga laporan menjadi tidak fokus." },
    { q: "Prinsip pengungkapan penuh (full disclosure) mengharuskan ...", options: ["Mengungkapkan semua informasi penting yang memengaruhi keputusan dalam laporan atau catatan atas laporan keuangan", "Menyembunyikan kerugian perusahaan", "Hanya mengungkapkan laba perusahaan", "Mengungkapkan gaji setiap karyawan"], answer: 0, solution: "1. Semua informasi yang relevan bagi pengguna harus diungkapkan, termasuk dalam catatan atas laporan keuangan. 2. Contohnya: metode akuntansi yang dipakai dan peristiwa penting setelah tanggal neraca. Kesalahan umum: mengira cukup mengungkapkan hal-hal yang menguntungkan saja." },
    { q: "Prinsip unit moneter menyatakan bahwa ...", options: ["Transaksi dicatat dalam satuan mata uang yang stabil", "Transaksi boleh dicatat dalam satuan apa pun", "Nilai karyawan harus dicatat sebagai aset", "Inflasi harus selalu disesuaikan"], answer: 0, solution: "1. Akuntansi mencatat transaksi dalam satuan mata uang (misalnya rupiah). 2. Hal yang tidak dapat diukur dengan uang, seperti kualitas manajemen, tidak dicatat. Kesalahan umum: mencatat hal non-kuantitatif sebagai aset." },
    { q: "Perbedaan utama basis akrual dan basis kas adalah ...", options: ["Basis akrual hanya untuk perusahaan besar", "Basis akrual mengakui pendapatan dan beban saat terjadi, sedangkan basis kas saat kas diterima/dibayar", "Basis kas lebih akurat untuk semua perusahaan", "Tidak ada perbedaan di antara keduanya"], answer: 1, solution: "1. Basis akrual mengakui transaksi saat hak/kewajiban timbul. 2. Basis kas baru mengakui saat kas berpindah tangan. 3. Standar akuntansi umum memakai basis akrual. Kesalahan umum: mengira keduanya menghasilkan laporan yang selalu sama." },
    { q: "Berdasarkan prinsip pengakuan pendapatan, pendapatan jasa diakui ...", options: ["Saat kas diterima dari pelanggan", "Saat jasa telah dikerjakan/diserahkan, walaupun kas belum diterima", "Saat kontrak ditandatangani", "Saat perusahaan membutuhkan kas"], answer: 1, solution: "1. Pendapatan diakui saat dihasilkan (earned), yaitu ketika jasa telah dikerjakan. 2. Penerimaan kas bisa terjadi sebelum (uang muka) atau sesudah (piutang). Kesalahan umum: mengakui pendapatan saat kas diterima — itu basis kas." },
    { q: "Perusahaan membeli tanah Rp500.000.000. Dua tahun kemudian nilai pasarnya Rp800.000.000. Berdasarkan prinsip biaya historis, tanah dicatat sebesar ...", options: ["Rp800.000.000", "Rp500.000.000", "Rp650.000.000", "Rp300.000.000"], answer: 1, solution: "1. Biaya historis mencatat aset sebesar harga perolehan. 2. Kenaikan nilai pasar yang belum terealisasi tidak diakui. 3. Maka tanah tetap dicatat Rp500.000.000. Kesalahan umum: mencatat sebesar nilai pasar Rp800.000.000." },
    { q: "Pemilik membayar uang sekolah anaknya dari kas perusahaan tanpa mencatat prive. Tindakan ini melanggar prinsip ...", options: ["Konservatisme", "Entitas ekonomi", "Periode akuntansi", "Biaya historis"], answer: 1, solution: "1. Uang sekolah anak adalah transaksi pribadi pemilik, bukan beban perusahaan. 2. Mencampurkannya melanggar prinsip entitas ekonomi yang memisahkan perusahaan dari pemilik. 3. Seharusnya dicatat sebagai prive. Kesalahan umum: menganggap semua kas keluar perusahaan otomatis menjadi beban." },
    { q: "Prinsip akuntansi yang menjadi dasar dibuatnya jurnal penyesuaian adalah ...", options: ["Biaya historis dan unit moneter", "Prinsip penandingan dan basis akrual", "Konservatisme dan materialitas", "Entitas ekonomi dan going concern"], answer: 1, solution: "1. Jurnal penyesuaian memastikan beban diakui pada periode yang sama dengan pendapatan yang dihasilkannya (penandingan). 2. Pengakuan dilakukan saat terjadi, bukan saat kas berpindah (basis akrual). 3. Contohnya: beban akrual, pendapatan akrual, dan depresiasi. Kesalahan umum: mengira penyesuaian hanya soal kerapian administrasi." }
  ]
};
